(window.GIM_TS=window.GIM_TS||{})["Bava Batra.2"]={"from":48,"a":[["\u0003כדנייד נכתמא אפומיה דחצבא\u0004 \u0005[כאשר ינוד המכסה על פי הכד]\u0006 אם מניחים אותו על החומה.","ועוד מסופר: \u0003דבי\u0004 \u0005[בבית]\u0006 \u0003בר מריון בריה\u0004 \u0005[בנו]\u0006 של \u0003רבין כי הוה נפצי כיתנא\u0004 \u0005[כאשר היו מנפצים את הפשתן],\u0006 \u0003הוה אזלא רקתא ומזקא אינשי\u0004 \u0005[היתה הנעורת הולכת ומזיקה\u0006 ל\u0005אנשים],\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבינא\u0004 להתלונן, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כי אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 \u0003מודה ר' יוסי בגירי דיליה\u0004 \u0005[בחיצים שלו]\u0006 שאסור הדבר, \u0003הני מילי דקא אזלא\u0004 \u0005[דברים אלה\u0006 אמורים דווקא כשההיזק \u0005הולך]\u0006 \u0003מכחו, הכא זיקא הוא דקא ממטי לה\u0004 \u0005[כאן הרוח היא שמביאה אותה]\u0006 את הנעורת.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר בר רב אשי: מאי שנא\u0004 \u0005[מה שונה]\u0006 הדבר \u0003מזורה\u0004 (זורק את התבואה ברוח על מנת שהמוץ יעוף) \u0003ורוח מסייעתו,\u0004 שהדבר נחשב כמלאכה גמורה לענין שבת, למרות שהרוח עושה מקצתה? ומסופר: \u0003אמרוה\u0004 את הבעיה היסודית ביחס לנעורת הפשתן \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003מרימר, אמר להו\u0004 \u0005[להם]:\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 דין \u0003זורה ורוח מסייעתו.\u0004","ושואלים: \u0003ולרבינא,\u0004 שאינו סבור כך, \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר\u0005]\u0006 \u0003מגץ היוצא מתחת הפטיש והזיק,\u0004 שלדעת הכל \u0003חייב לשלם?\u0004 ומשיבים: \u0003התם ניחא ליה דליזל\u0004 \u0005[שם נוח לו שילך]\u0006 הגץ רחוק ככל האפשר ולא ישאר סמוך, אבל \u0003הכא\u0004 \u0005[ כאן ]\u0006 \u0003לא ניחא ליה דליזל\u0004 \u0005[נוח לו שתלך]\u0006 הנעורת למרחוק.","\u0003לא יטע אדם אילן סמוך לשדה חבירו אלא אם כן הרחיק ממנו ארבע אמות, אחד גפנים ואחד כל אילן.\u0004 אם \u0003היה גדר בינתים\u0004 — \u0003זה סומך\u0004 את נטיעותיו \u0003לגדר מכאן וזה סומך\u0004 את תבואתו \u0003לגדר מכאן.\u0004","\u0003היו שרשים יוצאים לתוך\u0004 שדהו \u0003של חבירו\u0004 — \u0003מעמיק\u0004 בעל השדה וחופר בעומק \u0003שלשה טפחים\u0004 גם אם קוצץ את השורשים, \u0003כדי שלא יעכב את המחרישה.\u0004 ואם \u0003היה חופר\u0004 באותו מקום \u0003בור, שיח ומערה\u0004 ונתקל בשורשי אילן של חבירו — \u0003קוצץ ויורד\u0004 בחפירה לעומק כדרכו, \u0003והעצים\u0004 (חלקי השורש שקצץ) הם \u0003שלו.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003ארבע אמות שאמרו\u0004 חכמים להרחיק את גפניו משדה חבירו, הם \u0003כדי עבודת הכרם,\u0004 שלא ייכנסו לשדה חבירו השוורים והמחרישה כשמעבד את כרמו. \u0003אמר שמואל: לא שנו אלא בארץ ישראל, אבל בבבל\u0004 די ב\u0003שתי אמות. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003לא יטע אדם אילן סמוך לשדה חבירו, אלא אם כן הרחיק ממנו שתי אמות.\u0004 ויש לשאול: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 במשנה: \u0003ארבע אמות! אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003כ\u0004דברי \u0003שמואל,\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003ואיכא דרמי לה מירמא\u0004 \u0005[ויש\u0006 ששנה \u0005אותה\u0006 הלכה בדרך \u0005של הטלת סתירה].\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003לא יטע אדם אילן סמוך לשדה חבירו אלא אם כן הרחיק ממנו ארבע אמות, והתניא\u0004 \u0005[והרי שנויה\u0006 בברייתא\u0005]:\u0006 \u0003שתי אמות! אמר שמואל: לא קשיא\u0004 \u0005[קשה],\u0006 \u0003כאן בבבל, כאן בארץ ישראל.\u0004","מסופר: \u0003רבא בר רב חנן הוו ליה הנהו דיקלי אמיצרא דפרדיסא\u0004 \u0005[היו לו דקלים\u0006 שהיו עומדים \u0005על גבול הפרדס\u0006 של גפנים, כרם\u0005]\u0006 של \u0003רב יוסף, הוו אתו צפורי יתבי בדיקלי ונחתי בפרדיסא ומפסדי ליה\u0004 \u0005[היו באות צפורים יושבות בדקלים ו\u0006אחר כך היו \u0005יורדות אל הפרדס ומפסידות אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003זיל קוץ\u0004 \u0005[לך קצוץ]\u0006 את דקליך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא ארחיקי\u0004 \u0005[והרי הרחקתי]\u0006 \u0003לי\u0004 מרחק ראוי כדין! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003לאילנות, אבל לגפנים בעינן טפי\u0004 \u0005[צריכים אנו\u0006 בהרחקה \u0005יותר].\u0006","הקשה לו: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003אחד גפנים ואחד כל אילן! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 בין \u0003אילן לאילן ו\u0004בין \u0003גפנים לגפנים, אבל\u0004 בין \u0003אילן לגפנים בעינן טפי\u0004 \u0005[צריכים אנו יותר].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בר רב חנן: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לא קייצנא\u0004 \u0005[אקצוץ],\u0006 שכן \u0003אמר רב: האי דיקלא דטעין קבא אסור למקצייה\u0004 \u0005[דקל שטוען\u0006 מוציא פירות כדי \u0005קב אסור לקצוץ אותו]\u0006 משום \"בל תשחית\". \u0003ואמר ר' חנינא: לא שכיב\u0004 \u0005[מת]\u0006 \u0003שכחת ברי\u0004 \u0005[בני],\u0006 \u0003אלא\u0004 משום \u0003דקץ תאנתא בלא זימניה\u0004 \u0005[שקצץ תאנה בלא זמנה],\u0006 \u0003מר אי ניחא ליה, ליקוץ\u0004 \u0005[אדוני אם נוח לו\u0006 בכך, \u0005שיקצוץ]\u0006 אבל אני איני רוצה לעשות מעשה.","מסופר: \u0003רב פפא הוו ליה הנהו דיקלי אמיצרא\u0004 \u0005[היו לו דקלים על גבולו]\u0006 של \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע, אזל אשכחיה דהוה חפר וקא קאיץ\u0004 \u0005[הלך מצא אותו,\u0006 את רב הונא, \u0005שהיה חופר וקוצץ]\u0006 את \u0003שרשיו,\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי האי\u0004 \u0005[מה זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003היו שרשים יוצאים לתוך של חבירו\u0004 — \u0003מעמיק שלשה כדי שלא יעכב המחרישה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003שלשה\u0004 טפחים בלבד, ואולם \u0003מר קא חפר טפי\u0004 \u0005[אדוני חופר\u0006 ומעמיק \u0005יותר\u0006 משלושה\u0005]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003בורות שיחין ומערות קא חפרנא\u0004 \u0005[חופר אני],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003היה חופר בור, שיח ומערה\u0004 — \u0003קוצץ ויורד והעצים שלו. אמר רב פפא: אמרי ליה כולהי\u0004 \u0005[אמרתי לו כולם],\u0006 כלומר, הבאתי ראיות הרבה \u0003ולא יכילי ליה\u0004 \u0005[יכולתי לו]\u0006 לשכנע אותו,"],["\u0003עד דאמרי ליה הא\u0004 \u0005[שאמרתי לו\u0006 דבר \u0005זה]\u0006 ש\u0003אמר רב יהודה: מצר שהחזיקו בו רבים\u0004 — \u0003אסור לקלקלו.\u0004 ואף כאן, כיון שאני כבר השתמשתי במיצר ויש לי חזקה בו, אסור לך לקלקל את מה שיש לי. \u0003לבתר דנפק\u0004 \u0005[לאחר שיצא]\u0006 רב פפא, \u0003אמר\u0004 רב הונא בנו של רב יהושע: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא אמרי ליה\u0004 \u0005[אמרתי לו]:\u0006 \u0003כאן\u0004 שמועילה חזקה מדובר \u0003בתוך שש עשרה אמה,\u0004 שבתוך תחום זה השורשים נחשבים כחלק מן האילן, אבל \u0003כאן\u0004 הרי היה המעשה, שקצצתי את שורשי הדקלים, \u0003חוץ לשש עשרה אמה.\u0004","שנינו במשנה: \u0003היה חופר בור, שיח ומערה\u0004 — \u0003קוצץ ויורד והעצים שלו. בעא מיניה\u0004 \u0005[שאל אותו]\u0006 החכם \u0003יעקב הדייבא\u0004 \u0005[מהדייב]\u0006 \u0003מרב חסדא: עצים של מי?\u0004 כלומר, במשנה נאמר \"שלו\", ולא ברור לנו של מי, אם של בעל האילן או של בעל הקרקע.","\u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 במסכת מעילה: \u0003שרשי אילן של הדיוט הבאין ב\u0004תוך שדה \u0003של הקדש\u0004 — \u0003לא נהנין ולא מועלין,\u0004 שאסרו חכמים ליהנות מהם, ואולם אם עבר ונהנה משורשים אלה — אינו נחשב כמועל בהקדש.","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר,\u0006 מפרש\u0005]\u0006 כי \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003אילן אזלינן\u0004 \u0005[אנו הולכים]\u0006 והשורשים נחשבים כחלק ממנו — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא מועלין,\u0004 שהרי אילן זה הוא חולין. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003קרקע אזלינן\u0004 \u0005[אנו הולכים]\u0006 והשורשים שייכים לבעל הקרקע, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא מועלין?\u0004","ומקשים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אתה אומר? \u0003בתר אילן אזלינן\u0004 \u0005[אחר האילן אנו הולכים]?\u0006 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של משנה זו: שורשי אילן \u0003של הקדש הבאים בשל הדיוט לא נהנין ולא מועלין; ואי בתר\u0004 \u0005[אחר]\u0006 ה\u0003אילן אזלינן\u0004 \u0005[אנו הולכים],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא מועלין?\u0004","אלא \u0003מידי איריא\u0004 \u0005[כלום שייכים\u0006 הדברים\u0005]?\u0006 כאן \u0003בגידולין הבאין לאחר מכאן,\u0004 שצמחו לאחר שהקדיש את האילן \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003וקא סבר\u0004 \u0005[וסבור]\u0006 חכם זה במשנה ש\u0003אין מעילה בגידולין\u0004 שצמחו מן המוקדש","\u0003,\u0004 אלא בהקדש הראשוני. ואין לכך קשר לשאלה שלנו. \u0003רבינא אמר, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן בתוך שש עשרה אמה,\u0004 השורשים נחשבים כחלק מן האילן, \u0003כאן חוץ לשש עשרה אמה\u0004 השורשים נחשבים כחלק מן הקרקע בה הם מצויים.","\u0003אמר עולא: אילן הסמוך למצר בתוך שש עשרה אמה\u0004 — \u0003גזלן הוא,\u0004 שהרי הוא יונק מאדמת חבירו, \u0003ואין מביאין ממנו בכורים,\u0004 משום שהוא כמצוה הבאה בעבירה.","ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לעולא הא\u0004 \u0005[\u0006שיעור \u0005זה]?\u0006 \u0003אילימא מדתנן\u0004 \u0005[אם תאמר מ\u0006מה \u0005ששנינו\u0006 במשנה\u0005]:\u0006 \u0003עשר נטיעות\u0004 (אילנות צעירים) \u0003המפוזרות בתוך\u0004 שטח של \u0003בית סאה, חורשין כל בית סאה בשבילן עד ראש השנה\u0004 של שנת שביעית. שאף שאסור לחרוש קרקע אחרת לפני שביעית (שלא יהא כמכין לעבודת האדמה באותה שנה), לשם קיום האילנות הצעירים הותר לו.","ונעשה חשבון: \u0003כמה הוו להו\u0004 \u0005[הוא]\u0006 השטח של בית סאה? — \u0003תרי אלפין וחמש מאה גרמידי\u0004 \u0005[אלפיים וחמש מאות אמות\u0006 מרובעות\u0005].\u0006 \u0003לכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מן האילנות \u0003כמה מטי ליה\u0004 \u0005[מגיע לו],\u0006 מה השטח שהוא זקוק לו — \u0003מאתן וחמשין\u0004 \u0005[מאתיים וחמישים\u0006 אמות מרובעות\u0005],\u0006 אם כן \u0003הא לא הוי\u0004 \u0005[הרי אין זה]\u0006 המרחק ששנה \u0003עולא,\u0004 שהרי שטח של שש עשרה אמה לכל צד של האילן, שהוא ריבוע של שלושים ושתים אמה על שלושים ושתים אמה (אלף ועשרים וארבע אמות רבועות), גדול הרבה יותר ממאתיים וחמישים!","\u0003ואלא\u0004 יש לומר שלמד זאת \u0003מדתנן\u0004 \u0005[מ\u0006מה \u0005ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שלשה אילנות\u0004 גדולים אפילו היו \u0003של שלשה בני אדם\u0004 — \u0003הרי אלו מצטרפין\u0004 להיחשב שדה אילן לענין חריש בערב שביעית, \u0003וחורשין כל\u0004"],["\u0003בית סאה בשבילן; כמה הוו להו\u0004 \u0005[הם]\u0006 באמות? \u0003תרי אלפי וחמש מאה גרמידי\u0004 \u0005[אלפיים וחמש מאות אמה].\u0006 \u0003לכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מן האילנות \u0003כמה מטי ליה\u0004 \u0005[מגיע לו]?\u0006 \u0003תמני מאה ותלתין ותלתא ותילתא\u0004 \u0005[שמונה מאות ושלושים ושלוש ושליש],\u0006 אולם \u0003אכתי נפישי ליה\u0004 \u0005[עדיין מרובה הוא]\u0006 השיעור שקבע \u0003עולא\u0004 לפי זה! ומשיבים: \u0003לא דק\u0004 \u0005[דקדק]\u0006 בדבר.","ושואלים: \u0003אימור דאמרינן\u0004 \u0005[אמור שאנו אומרים]\u0006 ש\u0003לא דק לחומרא\u0004 \u0005[דקדק\u0006 בשיעורים \u0005להחמיר],\u0006 אבל \u0003לקולא\u0004 \u0005[להקל]\u0006 \u0003לא דק מי אמרינן\u0004 \u0005[דקדק האם אנו אומרים]?\u0006 שהרי הוא פוטר מביכורים עץ שלפי המשנה אינו יונק משדה חבירו!","ומשיבים: \u0003מי סברת בריבועא קא אמרינן\u0004 \u0005[האם סבור אתה\u0006 ש\u0005בריבוע אנו אומרים],\u0006 שמודד ריבוע של שש עשרה על שש עשרה מכל צד? \u0003בעיגולא קא אמרינן\u0004 \u0005[בעיגול אנו אומרים]!\u0006 שכן יוצאים שורשי האילן בעיגול מסביב, ושטח העיגול קטן משל ריבוע.","ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כמה מרובע יותר על העיגול?\u0004 — \u0003רביע\u0004 (רבע), אם כן \u0003פשו להו\u0004 \u0005[נשארו להם]\u0006 \u0003שבע מאה ושתין ותמניא\u0004 \u0005[שבע מאות וששים ושמונה]\u0006 אמות מרובעות לכל אילן, \u0003אכתי פש ליה פלגא דאמתא\u0004 \u0005[עדיין נשאר לו חצי אמה]\u0006 יתירה לפי חשבון המשנה! שהחשבון יצא קרוב יותר אם נחשוב שהאילן יונק במרחק שש עשרה אמה וחצי לכל צד. ומשיבים: \u0003היינו\u0004 \u0005[זהו]\u0006 הענין שאמרנו ש\u0003לא דק\u0004 \u0005[דקדק]\u0006 \u0003ולחומרא\u0004 \u0005[ולהחמיר]\u0006 \u0003לא דק\u0004 \u0005[דקדק],\u0006 שמביא ביכורים אפילו מעץ הרחוק רק שש עשרה אמה מן המצר, ולא שש עשרה וחצי.","ומנסים להביא ראיה נוספת נגד דברי עולא, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003הקונה אילן וקרקעו\u0004 — \u0003מביא\u0004 ביכורים \u0003וקורא\u0004 עליהם. \u0003מאי לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 גם אם קנה קרקע \u0003כל שהוא\u0004 עם האילן? ודוחים: \u0003לא,\u0004 הכוונה היא שקונה קרקע בשיעור \u0003שש עשרה אמה.\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו: \u0003קנה שני אילנות בתוך\u0004 קרקע \u0003של חבירו\u0004 — \u0003מביא\u0004 ביכורים \u0003ואינו קורא\u0004 משום שהאדמה אינה שלו. \u0003הא\u0004 \u0005[הרי]\u0006 אם היו \u0003שלשה\u0004 אילנות — \u0003מביא וקורא, מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר שקנה קרקע \u0003כל שהוא\u0004 עם האילנות? ודוחים: \u0003לא, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר שהיתה למוכר קרקע בת \u0003שש עשרה אמה\u0004 מסביב לאילנות ואותה הוא קנה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במקום אחר, \u0003ר' עקיבא אומר: קרקע\u0004 \u0003כל שהוא חייב בפאה ובבכורים, וכותבין עליו פרוזבול,\u0004"],["\u0003ונקנין עמה נכסים שאין להם אחריות,\u0004 שיכול למכור מיטלטלים (\"נכסים שאין להם אחריות\") בכל כמות שהיא אגב הקרקע, אף שהיא מצומצמת ביותר. ולעניינו, שנינו שם שקרקע כלשהו חייבת בביכורים, ולדברי עולא הרי האילן יונק מן הקרקע שמסביב ופטור מביכורים! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בחיטי\u0004 \u0005[בחיטים]\u0006 שמביאים מהן ביכורים, והן אינן צריכות יותר מקרקע כלשהו.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן],\u0006 \u0003דקתני\u0004 \u0005[\u0006ממה \u0005ששנה]:\u0006 \u0003כל שהוא,\u0004 ומשמע שאפילו בשיעור קטן ביותר, ובוודאי כל אילן צריך שיעור גדול יותר של קרקע. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ועוד מציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: \u0003אילן\u0004 ש\u0003מקצתו בארץ ומקצתו בחוץ לארץ\u0004 — הרי \u0003טבל\u0004 (פירות שצריכים להפריש מהם תרומות ומעשרות) \u0003וחולין\u0004 (פירות שפטורים מתרומות ומעשרות) \u0003מעורבין זה בזה,\u0004 שמחלק האילן שגדל בארץ צריך להפריש מעשר, וחלקו הגדל בחוץ לארץ פטור ממעשר, וכיון ששניהם גדלים באילן אחד הרי טבל וחולין מעורבים. אלו \u0003דברי רבי.\u0004","\u0003רבן שמעון בן גמליאל אומר:\u0004 אותו חלק של העץ \u0003הגדל בחיוב,\u0004 כלומר, בארץ ישראל — \u0003חייב,\u0004 והחלק \u0003הגדל בפטור,\u0004 בחוץ לארץ — \u0003פטור.\u0004 ומעירים: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003אלא דמר סבר\u0004 \u0005[שחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]:\u0006 \u0003יש ברירה,\u0004 שאנו מניחים שמה שינק האילן מארץ ישראל מצמיח פירות בצד האילן שנוטה לשם, ולהיפך. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבי, \u0005סבור]:\u0006 \u0003אין ברירה,\u0004 והכל מעורב.","","\u0003אבל\u0004 אם \u0003גדל\u0004 האילן כולו \u0003בפטור,\u0004 כלומר, בחוץ לארץ — \u0003דברי הכל פטור,\u0004 אף שיש לו שורשים שיונקים מארץ ישראל, ואם כן קשה הדבר לעולא!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — ש\u0003מפסיק צונמא\u0004 \u0005[סלע]\u0006 בין הארץ וחוץ לארץ, ואין האילן יונק מאדמת ארץ ישראל כלל. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מאי טעמיה\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי\u0004 שסבור שטבל וחולין מעורבים זה בזה? ומשיבים: \u0003דהדרי ערבי\u0004 \u0005[שחוזרים ומתערבים]\u0006 בגזע המשותף למעלה מן הקרקע.","\u0003ובמאי קא מיפלגי\u0004 \u0005[ובמה הם חלוקים]?\u0006 — \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רבי, \u0005סבור]:\u0006 \u0003אוירא\u0004 \u0005[האויר]\u0006 מה שגדל מעל פני הקרקע יחד \u0003מבלבל\u0004 מערב את היניקה שמשני הצדדים. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]:\u0006 \u0003האי לחודיה קאי והאי לחודיה קאי\u0004 \u0005[זה לבדו עומד וזה לבדו עומד],\u0006 אף שהם מחוברים.","ושואלים מצד אחר על דברי עולא: \u0003ושש עשרה אמה ותו לא\u0004 \u0005[ולא יותר]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מרחיקין את האילן מן הבור עשרים וחמש אמה,\u0004 הרי שהשורשים מגיעים ליותר משש עשרה אמה! \u0003אמר אביי: מיזל טובא אזלי\u0004 \u0005[ללכת, הולכים\u0006 השורשים \u0005יותר],\u0006 אבל \u0003אכחושי לא מכחשי\u0004 \u0005[להכחיש\u0006 את הקרקע \u0005אינם מכחישים]\u0006 \u0003אלא עד שש עשרה אמה, טפי לא מכחשי\u0004 \u0005[יותר\u0006 מזה \u0005אינם מכחישים\u0006 אותה\u0005].\u0006","ובענין זה מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר, בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ריש לקיש מר' יוחנן: אילן הסמוך למיצר בתוך שש עשרה אמה, מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גזלן הוא, ואין מביאין ממנו בכורים.\u0004 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אחד אילן הסמוך למיצר, ואחד אילן הנוטה\u0004 לחצר חבירו — \u0003מביא\u0004 ביכורים ממנו \u0003וקורא, שעל מנת כן הנחיל יהושע לישראל את הארץ,\u0004 שלא יקפידו על דברים אלה.","","\u0003אילן שהוא נוטה לשדה חבירו, קוצץ\u0004 בעל השדה \u0003מלא המרדע,\u0004 כלומר, בגובה של מלמד הבקר (המקל בו מכים ומכוונים את השוורים) \u0003על גבי המחרישה\u0004 במקום שבו הוא חורש, כדי שלא יעכבו אותו ענפי האילנות מלהשתמש בו. \u0003ובחרוב ובשקמה\u0004 שיש להם צל מרובה שמזיק לצמחים — קוצץ \u0003כנגד המשקולת,\u0004 כלומר, חותך בקו ישר מאונך בגבול בין השדות. ואם היה השדה מקום \u0003בית השלחין\u0004 (קרקע מושקית בידי אדם) — הרי קוצץ \u0003כל\u0004 סוגי \u0003האילן כנגד המשקולת. אבא שאול אומר: כל אילן סרק\u0004 קוצץ \u0003כנגד המשקולת\u0004 ואין צריך להקפיד.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003אבא שאול ארישא קאי\u0004 \u0005[על ראשה\u0006 של המשנה \u0005הוא עומד,\u0006 מתייחס\u0005]\u0006 לגבי אילן הנוטה לשדה חבירו, ומתיר לקצוץ כל אילן סרק כנגד המשקולת, ולא רק חרוב ושקמה. \u0003או אסיפא קאי\u0004 \u0005[על סופה של\u0006 המשנה \u0005הוא עומד,\u0006 מתייחס\u0005]\u0006 לגבי בית השלחין דווקא, ומתיר דווקא באילן סרק ולא אילנות אחרים?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 פתרון לדבר ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003בית השלחין, אבא שאול אומר: כל\u0004 סוגי \u0003האילן\u0004 קוצץ \u0003כנגד המשקולת, מפני שהצל רע לבית השלחין;\u0004 משמע שבזה אינו חולק, אלא \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003ארישא קאי\u0004 \u0005[על ראשה\u0006 של המשנה \u0005הוא עומד\u0006 מתייחס\u0005],\u0006 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת],\u0006 \u0003דקתני\u0004 \u0005[ששנה]:\u0006 \u0003כל אילן סרק; אי אמרת בשלמא ארישא קאי\u0004 \u0005[נניח אם אתה אומר על ראשה\u0006 של המשנה \u0005הוא עומד,\u0006 מתייחס\u0005],\u0006 \u0003היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003כל אילן, אלא אי אמרת אסיפא קאי\u0004 \u0005[אם אומר אתה על סופה הוא עומד,\u0006 מתייחס\u0005],\u0006 \u0003אילן סרק מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]?\u0006 שהרי התנא הראשון מתיר לקצוץ כל אילן שהוא! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003ארישא קאי\u0004 \u0005[לראשה הוא עומד,\u0006 מתייחס\u0005],\u0006 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003אילן שהוא נוטה לרשות הרבים\u0004 — \u0003קוצץ\u0004 את ענפיו עד \u0003כדי שיהא גמל עובר\u0004 מתחת לאילן \u0003ורוכבו\u0004 עליו. \u0003ר' יהודה אומר:\u0004 כדי שיוכל לעבור שם \u0003גמל טעון פשתן או חבילי זמורות. ר' שמעון אומר:\u0004 קוצץ את \u0003כל\u0004 ענפי \u0003האילן\u0004 הנוטים לרשות הרבים \u0003כנגד המשקולת\u0004 שלא יהא נטוי כלל מעל רשות הרבים, \u0003מפני הטומאה\u0004 שמא תהיה טומאת מת ברשות הרבים, ועל ידי האילן המאהיל היא מטמאה שטח גדול.","שואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור ש\u0003בנזקין בתר אומדנא דהשתא אזלינן\u0004 \u0005[אחר האומדן של עכשיו אנו הולכים]\u0006 ואין אנו דואגים לנזקים שיהיו אחר כך? שהרי במשנתנו נאמר שקוצץ את האילן עד גובהו של הגמל ולא יותר מזה, אף שוודאי יחזרו הענפים ויצמחו. \u0003אמר ריש לקיש:\u0004 הלכה זו \u0003במחלוקת\u0004 היא \u0003שנויה, ו\u0004שיטת \u0003ר' אליעזר היא; דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין עושין חלל תחת רשות הרבים,\u0004 לא \u0003בורות,\u0004 לא \u0003שיחין ו\u0004לא \u0003מערות; ר' אליעזר מתיר\u0004 לעשות בור אם כיסהו כיסוי חזק \u0003בכדי שתהא עגלה מהלכת וטעונה אבנים\u0004 ולא יקרוס. משמע שאם בזמן שעשה את הבור, יכול הכיסוי לשאת עגלה מלאה אבנים — מותר, ואף שבמשך הזמן הכיסוי הזה עשוי להירקב — אין חוששים לכך. \u0003ר' יוחנן אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שאוסרים לעשות חלל בכל מקרה. \u0003התם זימנין דמפחית ולאו אדעתיה\u0004 \u0005[שם פעמים שנפחת\u0006 הכיסוי \u0005ולא מדעתו],\u0006 שאינו שם לב לכך, ויכול לגרום לנזק, \u0003אבל הכא קמא קמא קא קייץ ליה\u0004 \u0005[כאן ראשון ראשון\u0006 שצומח \u0005קוצץ אותו],\u0006 שכיון שהדבר נראה לעין אין לחשוש.","","","שנינו במשנה שאילן שנוטה לרשות הרבים קוצץ כדי שיהא גמל עובר ורוכבו. \u0003ר' יהודה אומר: גמל טעון פשתן או חבילי זמורות. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם \u0003שיעורא\u0004 \u0005[השיעור]\u0006 של \u0003ר' יהודה נפיש\u0004 \u0005[מרובה\u0006 יותר\u0005],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003שיעורא דרבנן נפיש\u0004 \u0005[שיעורם של החכמים מרובה\u0006 יותר\u0005]?\u0006 מה גבוה יותר: גמל ורוכבו, או גמל טעון פשתן?","ומשיבים: \u0003פשיטא דשיעורא דרבנן נפיש\u0004 \u0005[פשוט ששיעורם של חכמים מרובה],\u0006 \u0003דאי סלקא דעתך שיעורא\u0004 \u0005[שאם יעלה על דעתך\u0006 לומר כי \u0005השיעור]\u0006 של \u0003ר' יהודה נפיש\u0004 \u0005[מרובה\u0006 יותר\u0005],\u0006 \u0003רבנן בשיעורא\u0004 \u0005[חכמים בשיעור]\u0006 של \u0003ר' יהודה היכי עבדי\u0004 \u0005[איך\u0006 הם \u0005עושים]?\u0006 שהרי מובן כי צריך לעבור שם גמל נושא מטען! \u0003ו\u0004תוהים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אומר אתה? כי \u0003שיעורא דרבנן נפיש\u0004 \u0005[שיעורם של חכמים מרובה\u0006 יותר\u0005]?\u0006 אם כן \u0003ר' יהודה בשיעורא דרבנן מאי עביד\u0004 \u0005[בשיעור של חכמים מה\u0006 הוא \u0005עושה]?\u0006 הרי פעמים שעובר שם גמל ורוכבו! ומשיבים: \u0003אפשר דגחין וחליף תותיה\u0004 \u0005[ש\u0006הרוכב \u0005מתכופף ועובר תחתיו]\u0006 אם אין הבדל גדול בגובה. שנינו במשנה, ש\u0003ר' שמעון אומר:\u0004 קוצץ את \u0003כל\u0004 ענפי \u0003האילן\u0004 הנוטים לרשות הרבים \u0003כנגד המשקולת, מפני הטומאה.\u0004 ומביאים כי על כך \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003מפני אהל הטומאה,\u0004 שיאהיל על טומאה המצויה ברשות הרבים, ויטמא בכך את כל מה שמתחתיו. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שזו הכוונה, ולשם מה היה צריך לומר לנו? הלא \u0003\"מפני הטומאה\" תנן\u0004 \u0005[שנינו]!\u0006","","ומשיבים: \u0003אי ממתניתין, הוה אמינא\u0004 \u0005[אם ממשנתנו\u0006 לבד \u0005הייתי אומר]\u0006 שהחשש הוא \u0003דלמא מייתי\u0004 \u0005[שמא יביא]\u0006 \u0003עורב טומאה\u0004 ויעמוד על ענפי העץ \u0003ושדי התם\u0004 \u0005[וישליך שם],\u0006 ומפני חשש אין מניחים את האילן לצמוח לעבר רשות הרבים, \u0003ו\u0004אולם אם היה זה הטעם הרי \u0003סגיא בדחלולי בעלמא\u0004 \u0005[מספיק\u0006 היה \u0005בדחליל בלבד],\u0006 להבריח את העורבים, על כן \u0003קא משמע לן\u0004",""],["\u0003חזקת הבתים, והבורות, והשיחין\u0004 (בורות מרובעים), \u0003והמערות\u0004 (בורות מקורים) המשמשים לאגירת מים, \u0003והשובכות\u0004 של יונים, \u0003והמרחצאות, ובית הבדין\u0004 שעוצרים בהם שמן, \u0003ובית השלחין\u0004 (שדות מושקים בידי אדם), \u0003והעבדים, וכל\u0004 דבר כיוצא בזה \u0003שהוא עושה פירות תדיר,\u0004 שהשימוש שבו נמשך כל ימות השנה — \u0003חזקתן שלש שנים מיום ליום,\u0004 ואם המחזיק באלה מביא הוכחה שהוא מחזיק ברכוש זה במשך שלוש שנים שלימות, יש להניח שהוא שלו. ואף אם יטען אדם אחר שרכוש זה היה שלו, או של אבותיו, קודם לכן — לא תתבטל בעלות המחזיק.","\u0003שדה הבעל\u0004 (המושקית במי גשמים) שאינה עושה פירות אלא בעונות מסויימות בשנה, \u0003חזקתה שלש שנים ואינן מיום ליום\u0004 שהרי אין מעבדים ונוטלים פירות משדות אלה ברציפות במשך שלוש השנים.","\u0003ר' ישמעאל אומר: שלשה חדשים\u0004 של חזקה \u0003ב\u0004שנה ה\u0003ראשונה, שלשה באחרונה, ו\u0004חזקה של \u0003שנים עשר חדש באמצע\u0004 — \u0003הרי\u0004 אלה \u0003שמונה עשר חדש,\u0004 ודי בהם לחזקת שדה הבעל.","\u0003ר' עקיבא אומר: חדש בראשונה, וחדש באחרונה, ושנים עשר חדש באמצע\u0004 — \u0003הרי ארבעה עשר חדש.\u0004","\u0003אמר ר' ישמעאל: במה דברים אמורים\u0004 שצריכים שמונה עשר חודש לשדה בעל? — דבר זה הוא \u0003בשדה לבן,\u0004 שדה של דגן, \u0003אבל בשדה אילן,\u0004 אם \u0003כנס את תבואתו ומסק את זיתיו\u0004 ו\u0003כנס את קייצו\u0004 (התאנים) — \u0003הרי אלו שלש שנים,\u0004 שכיון שאכל שלושה מיני פירות הרי זו חזקה כאילו ישב בשדה שלוש שנים.","\u0003אמר ר' יוחנן, שמעתי מהולכי אושא\u0004 מאלה שלמדו בסנהדרין באושא \u0003שהיו אומרים: מנין לחזקה\u0004 שהיא \u0003שלש שנים? משור המועד,\u0004 כיצד? — \u0003מה שור המועד, כיון שנגח שלש נגיחות\u0004 ופגע בזדון באחרים — \u0003נפק ליה\u0004 \u0005[יצא לו]\u0006 \u0003מחזקת תם, וקם ליה\u0004 \u0005[ועמד לו]\u0006 מאז \u0003בחזקת מועד, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון\u0004 ש\u0003אכלה תלת שנין\u0004 \u0005[שלוש שנים]\u0006 — \u0003נפק\u0004 \u0005[יצאה]\u0006 \u0003לה\u0004 הנחלה \u0003מרשות מוכר וקיימא לה\u0004 \u0005[ועומדת היא]\u0006 \u0003ברשות\u0004 ה\u0003לוקח.\u0004","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מה שור המועד עד נגיחה רביעית לא מיחייב\u0004 \u0005[אינו מתחייב],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003עד שנה רביעית לא קיימא ברשותיה\u0004 \u0005[אינה עומדת ברשותו]!\u0006 ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003מכי\u0004 \u0005[מכאשר],\u0006 מהזמן שבו \u0003נגח שלש נגיחות הוי\u0004 \u0005[הריהו]\u0006 \u0003מועד,\u0004"],["\u0003ואידך\u0004 \u0005[האחרת,\u0006 הנגיחה הרביעית\u0005],\u0006 אינה כדי לעשותו מועד, כי שור זה כבר מועד הוא, אלא שקודם לכן \u0003כי לא נגח מאי לשלם\u0004 \u0005[כאשר אינו נוגח מה ישלם]?\u0006 \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003כיון\u0004 ש\u0003אכלה תלת שני\u0004 \u0005[שלוש שנים]\u0006 \u0003קיימא לה ברשותיה\u0004 \u0005[עומדת היא ברשותו]\u0006 של הקונה מיד.","ושואלים: \u0003אלא מעתה,\u0004 לפי הסבר זה, שמקור דין חזקה הוא בשור המועד, גם \u0003חזקה שאין עמה טענה\u0004 אם אין לו למחזיק טענה לבעלות אלא חזקה בלבד, \u0003תיהוי\u0004 \u0005[תהיה]\u0006 \u0003חזקה! אלמה תנן\u0004 \u0005[למה שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל חזקה שאין עמה טענה,\u0004 שאף שיכול להוכיח שהחזיק במקום, אם אין לו גם טענה להסביר את זכותו להיות שם — \u0003אינה חזקה!\u0004","ומתרצים: \u0003טעמא\u0004 \u0005[טעם]\u0006 הדבר שחזקה מועילה \u0003מאי\u0004 \u0005[מהו]?\u0006 — \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 אף שהמערער מוכיח ששלו היתה השדה, מכל מקום מאחר שזה מחזיק בשדה \u0003דלמא כדקאמר השתא\u0004 \u0005[שמא\u0006 האמת היא \u0005כפי שהוא אומר עכשיו]\u0006 שהוא טוען שיש לו זכות קניינית בשדה. ואולם אם \u0003איהו\u0004 \u0005[הוא]\u0006 עצמו \u0003לא טעין\u0004 \u0005[טוען],\u0006 \u0003אנן ליטעון ליה\u0004 \u0005[אנו נטען לו]?\u0006 שאין החזקה אלא ראיה לטענת הבעלות.","ועוד \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על הסבר זה \u0003רב עוירא: אלא מעתה, מחאה\u0004 שמוחה המערער \u0003שלא בפניו\u0004 של המחזיק במשך אותן שלוש שנים \u0003לא תיהוי\u0004 \u0005[תהיה,\u0006 תיחשב\u0005]\u0006 \u0003מחאה;\u0004 כי נאמר \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שור\u0004 ה\u0003מועד, מה שור המועד בפניו בעינן\u0004 \u0005[צריכים אנו]\u0006 להתרות, \u0003אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003בפניו בעינן\u0004 \u0005[צריכים אנו]\u0006 שימחה!","ומשיבים: זו אינה קושיה, שכן \u0003התם\u0004 \u0005[שם]\u0006 \u0003\"והועד בבעליו\"\u0004 (שמות כא, כט) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ולכן צריך להתרות דווקא בפני הבעלים. \u0003הכא, חברך חברא אית ליה, וחברא דחברך חברא אית ליה\u0004 \u0005[כאן, חברך חבר יש לו, וחבר של חברך חבר יש לו]\u0006 והדבר נודע ואינו צריך להודיע לו בפניו, שהרי אין כאן גזירת הכתוב שיצטרך להודיע בפני הבעלים.","ועוד שואלים: \u0003ול\u0004דעת \u0003ר' מאיר\u0004 ש\u0003אמר:\u0004 אם שור ש\u0003ריחק נגיחותיו,\u0004 שנגח בהפסק יום בין פעם לפעם \u0003חייב,\u0004 אם \u0003קירב נגיחותיו\u0004 כגון שנגח שלוש פעמים מיד בזו אחר זו \u0003לא כל שכן,\u0004 ולדעתו אין צריך שיגח בשלושה ימים שונים, אלא אפילו נגח שלוש פעמים באותו יום נעשה מועד, אם כן נאמר בהשוואה לכך שאם \u0003אכלה תלתא פירי בחד יומא\u0004 \u0005[שלושה פירות ביום אחד]\u0006 \u0003כגון תאנה,\u0004 שיכול להיות שהוא קוטף ממנה פעם אחת, ופעם שניה ושלישית ביום אחד, \u0003ליהוי\u0004 \u0005[שתהיה\u0006 זו\u0005]\u0006 \u0003חזקה!\u0004","ומשיבים: אין לומר כן בענין חזקה, ודווקא מפני שצריכה להיות \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שור המועד, מה שור המועד בעידנא דאית ליה הא נגיחה ליתא להא נגיחה\u0004 \u0005[בזמן שיש לו נגיחה זו אין את הנגיחה הזו],\u0006 שהרי הוא נוגח בכל אחת לעצמה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003בעידנא דאיתא להאי פירא ליתא להאי פירא\u0004 \u0005[בזמן שיש את הפרי הזה אין את הפרי הזה\u0006 האחר\u0005].\u0006 אבל כאשר כל הפירות נמצאים בשדה בבת אחת, אין זו נקראת חזקה, גם אם הוא נוטל את הפירות בשלוש פעמים שונות.","ומקשים: לפי זה אם \u0003אכלה תלתא פרי בתלתא יומי\u0004 \u0005[שלושה פירות בשלושה ימים]\u0006 \u0003כגון צלף\u0004 שמוציא פירות שמבשילים יום אחר יום, אם כן \u0003ליהוי\u0004 \u0005[שתהיה\u0006 זו\u0005]\u0006 \u0003חזקה!\u0004 ומשיבים: \u0003התם פירא מיהא איתיה, ומגמר\u0004 \u0005[שם הפרי מכל מקום ישנו, ולהיגמר\u0006 להתבשל\u0005]\u0006 \u0003הוא דקא גמר ואזיל\u0004 \u0005[שנגמר והולך]\u0006 בשלושה ימים. ולכן אינו דומה לשור הנוגח, שכל נגיחה עומדת לעצמה.","ומקשים: אם כן, \u0003כאשר\u0004 \u0003אכלה תלתא פירי בתלתין יומי\u0004 \u0005[שלושה פירות בשלושים יום],\u0006 \u0003כגון אספסתא\u0004 \u0005[אספסת]\u0006 שקוצרים אותה, והיא חוזרת וגדילה, וחוזרים וקוצרים אותה במשך זמן קצר, אם כן \u0003ליהוי\u0004 \u0005[שתהיה\u0006 זו\u0005]\u0006 \u0003חזקה!\u0004 ומשיבים: והרי \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 — \u0003דקדיח\u0004 \u0005[שגדל קצת]\u0006 וחתך \u0003ואכלה, דקדיח\u0004 \u0005[שגדל קצת]\u0006 \u0003ואכלה,\u0004 וכך קצר שלוש פעמים במשך חודש אחד, \u0003התם משמט\u0004 \u0005[שם לשמוט]\u0006 \u0003הוא דקא שמיט ואכיל\u0004 \u0005[ששומט ואוכל],\u0006 שאין זו דרך השימוש הרגילה באספסת להחשיב אדם כמחזיק בקרקע זו, אלא רק כאשר ממתין עד שתגדל האספסת היטב ואז קוצר אותה.","ומקשים: אם כן, \u0003אכלה תלתא פירי בתלתא ירחי\u0004 \u0005[שלושה פירות בשלושה חודשים],\u0006 \u0003כגון אספסתא\u0004 \u0005[אספסת]\u0006 שממתינים חודש שלם עד שתגדל, ושוב קוצרים וחוזרים וקוצרים לאחר חודש, שזו דרכה, \u0003ליהוי\u0004 \u0005[שתהיה\u0006 זו\u0005]\u0006 \u0003חזקה!\u0004 ומשיבים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003הולכי אושא\u0004 שלשיטתם אנו מדברים? \u0003ר' ישמעאל\u0004 הוא, ו\u0003לר' ישמעאל הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן],\u0006 שהוא סובר שחזקה היא.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' ישמעאל אומר: במה דברים אמורים\u0004 שצריך שלוש שנים? — \u0003בשדה הלבן,\u0004 שדה דגן, שעושה תבואה פעם בשנה, \u0003אבל בשדה אילן,\u0004 אם \u0003כנס את תבואתו ומסק את זיתיו וכנס את קייצו\u0004 — \u0003הרי אלו שלש שנים,\u0004 ובאמת הוא סבור שדי בשלוש אכילות.","ושואלים: \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 החולקים על ר' ישמעאל, \u0003מאי\u0004 \u0005[מה]\u0006 הראיה לענין זה של חזקה לשלוש שנים?","\u0003אמר רב יוסף: קרא כתיב\u0004 \u0005[מקרא נאמר]\u0006 כאשר קנה ירמיהו שדה מאת חנמאל בן דודו בזמן המצור: \u0003\"שדות בכסף יקנו וכתוב בספר וחתום\"\u0004 (ירמיה לב, מד), שיש לכתוב תעודה המוכיחה בעלות על השדה, כיון שלא יוכל לשבת בה שלוש שנים ובכך להוכיח את בעלותו עליה, \u0003שהרי נביא עומד ב\u0004שנת \u0003עשר\u0004 למלך צדקיהו \u0003ומזהיר\u0004 לכתוב את השטרות \u0003על\u0004 (בגלל) שנה \u0003אחת עשרה,\u0004 שבה תחרב הארץ. משמע שבשתי שנים בלבד אין זו חזקה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דלמא התם\u0004 \u0005[שמא שם]\u0006 רק \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמוטב לו שיהיו בידו שטרות ולא יזדקק לעדים על חזקה, אבל אין זו הוכחה שבפחות משלוש שנים אינה חזקה!"],["\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שיש כאן רק עצה טובה, מה שנאמר \u0003\"בנו בתים ושבו ונטעו גנות ואכלו את פרין\"\u0004 (ירמיה כט, ה), \u0003מאי קאמר\u0004 \u0005[מה\u0006 הוא \u0005אומר]\u0006 לענין הלכה? \u0003אלא עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בכך, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו].\u0006 ומעירים: \u0003תדע\u0004 שכן הוא, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונתתם בכלי חרש למען יעמדו ימים רבים\"\u0004 (ירמיה לב, יד), וזו בוודאי אינה אלא עצה טובה כיצד לשמור את הדברים כראוי, ואין זו הוראה להלכה. ואם כן, אין מכאן ראיה לחזקת שלוש שנים.","\u0003אלא\u0004 יש לחזור מהסבר זה ולומר הסבר אחר, וכך \u0003אמר רבא: שתא קמייתא מחיל איניש\u0004 \u0005[שנה ראשונה מוחל אדם]\u0006 על מה שאוכלים משלו ושותק ואינו מוחה, \u0003תרתי מחיל\u0004 \u0005[שתים מוחל],\u0006 \u0003תלת לא מחיל\u0004 \u0005[שלוש אינו מוחל].\u0006 ואם לא מחה בשנה השלישית מורה הדבר שאין הקרקע שלו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 לפי סברה זו, \u0003כי הדרא ארעא\u0004 \u0005[כאשר\u0006 מתברר שאכן קרקע זו של המערער, ו\u0005חוזרת הקרקע\u0006 לבעליה\u0005],\u0006 \u0003תיהדר לבר מפירי\u0004 \u0005[שתחזור חוץ מן פירות]\u0006 שלקח ממנה בשתי שנים אלה, שהרי מחל עליהם! \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003אמר רב נחמן: הדרא ארעא והדרי פירי\u0004 \u0005[חוזרת הקרקע וחוזרים הפירות]?\u0006","\u0003אלא\u0004 יש לחזור מתירוץ זה, וכך \u0003אמר רבא: שתא קמייתא לא קפיד איניש\u0004 \u0005[שנה ראשונה אין אדם מקפיד],\u0006 לבוא ולמחות (אף שאינו מוחל על הפירות), \u0003תרתי לא קפיד\u0004 \u0005[שתים אינו מקפיד],\u0006 \u0003תלת קפיד\u0004 \u0005[שלוש מקפיד].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה, כגון הני\u0004 \u0005[אלה]\u0006 \u0003דבי\u0004 \u0005[של בית]\u0006 \u0003בר אלישיב דקפדי\u0004 \u0005[ש\u0006הם \u0005מקפידים]\u0006 \u0003אפילו אמאן דחליף אמיצרא דידהו\u0004 \u0005[על מי שעובר על גבול\u0006 השדה \u0005שלהם],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003דלאלתר הוי\u0004 \u0005[שמיד הריהי]\u0006 \u0003חזקה\u0004 אם משתמש אדם שימוש כלשהו ברכושם? \u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך\u0006 הוא \u0005גם כן],\u0006 שבמקרה כגון זו תהא חזקה מיד, \u0003אם כן, נתת דבריך לשיעורין!\u0004 שיימצא שלכל אדם יש שיעור אחר של חזקה, ואי אפשר לומר כן.","\u0003אלא אמר רבא: שתא קמייתא מיזדהר איניש בשטריה\u0004 \u0005[שנה ראשונה נזהר אדם בשטרו]\u0006 ושומר את שטר הקנין של השדה, \u0003תרתי ותלת מיזדהר\u0004 \u0005[שתים ושלוש נזהר],\u0006 \u0003טפי לא מיזדהר\u0004 \u0005[יותר\u0006 מזה \u0005אינו נזהר]\u0006 ומשליך את השטר, אם לא ערערו על חזקתו בשדה. ולכן אמרו שאחרי שלוש שנים תהיה זו חזקה ולא יזדקק שוב לשטר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 לפי סברה זו, \u0003מחאה שלא בפניו לא תיהוי\u0004 \u0005[תהיה,\u0006 תיחשב\u0005]\u0006 ל\u0003מחאה,\u0004 ואם יעברו שלוש שנים בלא מחאה בפניו — תהא זו חזקה, אף שמוחה הלה בפני אנשים אחרים ואנו יודעים שאינו מתכוון לוותר על שדהו. וזאת רק משום \u0003דאמר ליה\u0004 \u0005[\u0006שיכול \u0005לומר לו]:\u0006 \u0003אי מחית באפאי, הוה מיזדהרנא בשטראי\u0004 \u0005[אם היית מוחה בפני, הייתי נזהר בשטרי]\u0006 ולא הייתי זורק אותו!","ומשיבים: \u0003דאמר ליה\u0004 \u0005[\u0006שיכול המוחה \u0005לומר לו]:\u0006 \u0003חברך חברא אית ליה, וחברא דחברך חברא אית ליה\u0004 \u0005[חברך חבר יש לו, והחבר של חברך חבר יש לו]\u0006 ואפשר לסמוך על כך שהמחאה תגיע לאוזניך.","\u0003אמר רב הונא: שלש שנים שאמרו, הוא שאכלן רצופות.\u0004 ותוהים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה במשנה: \u0003חזקתן שלש שנים מיום ליום!\u0004 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003\"מיום ליום\"\u0004 הרי זה בא \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003מקוטעות,\u0004 לומר שמדובר בשלוש שנים שכל אחת מהן אכל ברצף, \u0003ולעולם אפילו מפוזרות,\u0004 כלומר, אף אם אכל שנה והפסיק שנה, ושוב אכל שנה. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב הונא שצריכות הן להיות רצופות.","\u0003אמר רב חמא: ומודי\u0004 \u0005[ומודה]\u0006 \u0003רב הונא, באתרי דמוברי באגי\u0004 \u0005[במקומות ש\u0006בהם \u0005מובירים\u0006 את \u0005השדות]\u0006 שזורעים את השדה שנה אחת ומשאירים אותו בור בשנה האחרת, שבמקרה כזה מצטרפות שלוש שנות היבול, למרות שיש ביניהן הפסק.","ואומרים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא למקום \u0003דאיכא דמובר ואיכא דלא מובר\u0004 \u0005[שיש שמוביר ויש שאינו מוביר]\u0006 \u0003והאי גברא מוברה\u0004 \u0005[ואדם זה הוביר אותה],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003אמר ליה\u0004 \u0005[יאמר לו]\u0006 הטוען: \u0003אם איתא דדידך הואי, איבעי לך למיזרעה\u0004 \u0005[אם כן הוא ששלך היתה, היית צריך לזרוע אותה],\u0006 ועל כן \u0003קא משמע לן דאמר ליה\u0004 \u0005[השמיע לנו ש\u0006יכול הוא \u0005לומר לו]:\u0006 \u0003חדא ארעא בכוליה באגא לא מצינא לינטר\u0004 \u0005[קרקע אחת\u0006 זרועה \u0005בכל הבקעה איני יכול לשמור],\u0006 ולכן גם אני עשיתי כאחרים והשארתי אותה מוברת.","\u0003ואי נמי\u0004 \u0005[או גם כן]\u0006 יכול לומר לו: \u0003בהכי ניחא\u0004 \u0005[בכך נוח]\u0006 \u0003לי דעבדא טפי\u0004 \u0005[ש\u0006היא \u0005עושה\u0006 אחר כך \u0005יותר]\u0006 ואיני רוצה לזורעה שנה אחר שנה ולגרום שיכחיש כוחה.","על דברי רב הונא, שהחזקה צריכה שתהא רצופה ממש, מקשים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003חזקת הבתים; והא\u0004 \u0005[והרי]\u0006 \u0003בתים דביממא ידעי\u0004 \u0005[שביום יודעים]\u0006 מי יושב בהם, \u0003בליליא לא ידעי\u0004 \u0005[בלילה אין יודעים],\u0006 מדוע נחשבת זו חזקה? והרי אין היא רצופה!","\u0003אמר אביי: מאן מסהיד\u0004 \u0005[מי מעיד]\u0006 על \u0003בתים?\u0004 — \u0003שיבבי\u0004 \u0005[השכנים],\u0006 \u0003שיבבי מידע ידעי ביממא ובליליא\u0004 \u0005[השכנים יודעים\u0006 מי נמצא \u0005ביום ובלילה].\u0006","\u0003רבא אמר:\u0004 איך אפשר להעיד על שימוש רצוף בבתים — \u0003כגון דאתו בי תרי ואמרי\u0004 \u0005[שבאים שניים ואומרים]:\u0006 \u0003אנן אגרינן מיניה, ודרינן ביה תלת שנין ביממא ובליליא\u0004 \u0005[אנו שכרנו\u0006 את הבית \u0005ממנו, וגרנו בו שלוש שנים ביום ובלילה]\u0006 ועדות זו שלהם מועילה כדי שיוחזק הבית בידי האיש שהשכיר להם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי:\u0004 מדוע סומכים על שני עדים כאלה? הלא \u0003הני\u0004 \u0005[אלה]\u0006 \u0003נוגעין בעדותן הן, דאי לא אמרי הכי\u0004 \u0005[שאם אינם אומרים כך]\u0006 שאינם מעידים ששכרו את הבית מן המחזיק במשך שלוש שנים רצופות, \u0003אמרינן להו\u0004 \u0005[אומרים אנו להם]:\u0006 \u0003זילו הבו ליה אגר ביתא להאי\u0004 \u0005[לכו\u0006 ו\u0005תנו לו\u0006 את \u0005שכר הבית לזה]\u0006 שהוא הטוען שהוא בעל הבית האמיתי!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דייני דשפילי הכי דאיני\u0004 \u0005[דיינים שפלים,\u0006 בורים, \u0005כך\u0006 הם \u0005דנים].\u0006 \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 במקרה \u0003כגון דנקיטי אגר ביתא ואמרי\u0004 \u0005[ש\u0006הם \u0005מחזיקים\u0006 בידם את \u0005שכר הבית ואומרים]:\u0006 \u0003למאן ליתביה\u0004 \u0005[למי לתת אותו]?\u0006 ואם כן אינם נוגעים בעדותם, שלא איכפת להם מי יקבל מידם את השכר.","\u0003אמר מר זוטרא, ואי טעין ואמר\u0004 \u0005[ואם\u0006 המערער \u0005טוען ואומר]:\u0006 \u0003ליתו תרי סהדי לאסהודי ליה דדר ביה תלת שני ביממא ובליליא\u0004 \u0005[שיבואו שני עדים להעיד לו שגר בו\u0006 בבית \u0005שלוש שנים ביום ובלילה],\u0006 \u0003טענתיה\u0004 \u0005[טענתו]\u0006 \u0003טענה\u0004 ושומעים לו, שבלי זה אין זו ראיה גמורה."],["\u0003ומודי\u0004 \u0005[ומודה]\u0006 \u0003מר זוטרא, ברוכלין המחזירין\u0004 (הסובבים) \u0003בעיירות\u0004 שבא אדם ודר בביתם, \u0003דאף על גב דלא טען\u0004 \u0005[שאף על פי שאינו טוען]\u0006 שרצונו בעדות על שימוש רצוף ביום ובלילה במשך שלוש שנים — \u0003טענינן ליה אנן\u0004 \u0005[אנו,\u0006 בית הדין, \u0005טוענים לו]\u0006 שכיון שיודעים אנשים שהוא מחזר בעיירות, שמא באו אנשים וגרו בביתו שלא ברשות בזמנים שהוא לא ידע על כך.","ולעצם הצורך בשימוש רצוף של יום ולילה במשך כל שנות החזקה, מעירים: \u0003ומודה רב הונא, בחנותא\u0004 \u0005[בחנות]\u0006 של \u0003מחוזא דליממא עבידא, לליליא לא עבידא\u0004 \u0005[שליום\u0006 היא \u0005עשויה,\u0006 ו\u0005ללילה אינה עשויה]\u0006 שאינו צריך להשתמש בה בלילה.","ובענין זה של רצף השימוש הנחוץ לחזקה, מסופר: \u0003רמי בר חמא ורב עוקבא בר חמא זבון ההיא אמתא בהדי הדדי\u0004 \u0005[קנו שפחה\u0006 אחת \u0005ביחד,\u0006 בשותפות\u0005],\u0006 \u0003מר אישתמש\u0004 \u0005[חכם זה השתמש]\u0006 \u0003בה\u0004 שנה \u0003ראשונה שלישית וחמישית, ומר אישתמש\u0004 \u0005[וחכם זה השתמש]\u0006 \u0003בה\u0004 שנה \u0003שניה רביעית וששית; נפק ערער עילוה\u0004 \u0005[יצא ערעור עליה]\u0006 שטען אדם שהשפחה אינה שייכת להם, אלא שלו היא.","\u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבא\u0004 לדון, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי טעמא עבדיתו הכי\u0004 \u0005[מה טעם עשיתם\u0006 אתם \u0005כך]\u0006 שלא החזקתם בה ברציפות? \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תחזקו אהדדי\u0004 \u0005[תהיה לכם חזקה זה על זה],\u0006 והואיל וכך, \u0003כי היכי דלדידכו לא הוי\u0004 \u0005[כמו שלכם אין זו]\u0006 \u0003חזקה\u0004 — \u0003לעלמא נמי לא הוי\u0004 \u0005[\u0006ביחס \u0005לעולם,\u0006 לשאר אנשים, \u0005גם כן אין זו]\u0006 \u0003חזקה.\u0004","ומוסיפים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 באופן ש\u0003לא כתוב עיטרא\u0004 \u0005[נכתב\u0006 הדבר ב\u0005שטר],\u0006 ששותפים הם ומתחלקים בשימוש ביניהם. \u0003אבל\u0004 אם \u0003כתוב עיטרא\u0004 \u0005[נכתב שטר]\u0006 — \u0003קלא אית ליה\u0004 \u0005[קול יש לו]\u0006 לדבר, שאין כל אחד מהם מחזיק בנפרד, אלא שניהם יחד, ואם לא ערערו הבעלים בתוך שלש שנים, אפשר לסמוך על החזקה.","ובהמשך לדיון בצורך בשימוש מלא בקרקע בזמן החזקה. \u0003אמר רבא: אכלה\u0004 את השדה \u0003כולה\u0004 במשך שנות חזקה \u0003חוץ מבית רובע\u0004 שלא השתמש בו — \u0003קנה\u0004 את \u0003כולה\u0004 בחזקה, \u0003חוץ מבית רובע\u0004 זה.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 שאותו בית רובע \u0003בר זריעה היא,\u0004 שניתן המקום להיזרע, \u0003אבל\u0004 אם \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בר זריעה היא\u0004 — \u0003קני לה אגב ארעא\u0004 \u0005[קונה אותו אגב\u0006 שאר \u0005הקרקע] .\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ביבי בר אביי:\u0004 \u0003אלא מעתה, צונמא\u0004 (מקום סלעים) בלבד \u0003במה,\u0004 באיזה מעשה של חזקה, \u0003יקנה\u0004 אותו? \u0003אלא\u0004 צריך לומר שגם לצונמא יש חזקה \u0003באוקומי\u0004 \u0005[בהעמדה]\u0006 \u0003בה חיותא\u0004 \u0005[בהמות]\u0006 \u0003ומשטחא\u0004 \u0005[ושטיחה]\u0006 \u0003בה פירי\u0004 \u0005[פירות],\u0006 \u0003הכא נמי איבעי ליה לאוקומי\u0004 \u0005[כאן גם כן היה צריך לו להעמיד]\u0006 \u0003בה חיותא\u0004 \u0005[בהמות],\u0006 \u0003אי נמי משטחא\u0004 \u0005[או גם כן לשטוח]\u0006 \u0003בה פירי\u0004 \u0005[פירות],\u0006 ואם לא עשה כל שימוש בחלקה קטנה זו כשלעצמה, נמצא שלא החזיק בה, וכפי שהוא בקרקע בת זריעה.","מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006 \u0003מאי בעית בהאי ביתא\u0004 \u0005[מה אתה מבקש,\u0006 עושה, \u0005בבית זה]\u0006 שאתה נמצא בו, שהוא שלי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מינך זבינתיה ואכלית\u0004 \u0005[ממך קניתי אותו ואכלתי אותו,\u0006 השתמשתי בו\u0005]\u0006 \u0003שני\u0004 (שנות) \u0003חזקה.\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא בשכוני גוואי הואי\u0004 \u0005[אני באיזורי היישוב,\u0006 במקום רחוק \u0005הייתי].\u0006 ולא מכרתי לך מעולם, ולא ידעתי שאתה מצוי בבית, ולכן לא מחיתי בך.","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 המחזיק \u0005לפני]\u0006 \u0003רב נחמן\u0004 לדין, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל\u0004 \u0005[לך]\u0006 \u0003ברור אכילתך,\u0004 שעליך קודם להביא ראיות גמורות שבאמת השתמשת במקום שלוש שנים, ואז אפשר יהיה לדון בו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: הכי דינא\u0004 \u0005[כך הדין]?\u0006 הלא \u0003המוציא מחבירו עליו הראיה\u0004 והטוען הוא הצריך להוכיח שהבית הוא שלו!","ומעירים: \u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003רבא\u0004 על דברי \u0003רבא, ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003רב נחמן\u0004 על דברי \u0003רב נחמן; דההוא\u0004 \u0005[ש\u0006אדם \u0005אחד]\u0006"],["\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006 \u0003כל נכסי דבי\u0004 \u0005[הנכסים של בית]\u0006 משפחת \u0003בר סיסין\u0004 שיש בידי \u0003מזבינא\u0004 \u0005[מוכר אני]\u0006 \u0003לך. הואי ההיא ארעא דהוה מיקרי\u0004 \u0005[היתה\u0006 לו למוכר גם \u0005קרקע אחת שהיתה נקראת]\u0006 \u0003\"דבי\u0004 \u0005[של בית]\u0006 \u0003בר סיסין\". אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא לאו דבי\u0004 \u0005[\u0006קרקע \u0005זו לא של בית]\u0006 \u0003בר סיסין היא, ואיקרויי הוא דמיקריא \"דבי\u0004 \u0005[ו\u0006רק \u0005נקראת היא של בית]\u0006 \u0003בר סיסין\",\u0004 ואין היא בכלל מה שהוסכם בינינו. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב נחמן\u0004 לדין, \u0003אוקמא\u0004 \u0005[והעמיד]\u0006 רב נחמן את הקרקע \u0003בידא\u0004 \u0005[ביד]\u0006 ה\u0003לוקח\u0004 (הקונה). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 וכי \u0003דינא הכי\u0004 \u0005[הדין כך\u0006 הוא\u0005]?\u0006 והלא \u0003המוציא מחבירו עליו הראיה\u0004 וצריכה הקרקע להישאר ביד המוכר!","ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבא\u0004 על דברי \u0003רבא,\u0004 שכאן הוא סבור שבעל הקרקע הראשון הוא הנחשב מוחזק, ובמקרה הקודם הוא סבור שהקונה נחשב המוחזק. וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רב נחמן\u0004 על דברי \u0003רב נחמן\u0004 באותו ענין, ולהיפך.","ומתרצים: מדברי \u0003רבא\u0004 על דברי \u0003רבא לא קשיא\u0004 \u0005[קשה],\u0006 \u0003התם\u0004 \u0005[שם]\u0006 ב\"נכסי בר סיסין\", ה\u0003מוכר קאי בנכסיה\u0004 \u0005[עומד,\u0006 מוחזק \u0005בנכסיו],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 ב\"שיכוני גואי\", ה\u0003לוקח קאי בניכסיה\u0004 \u0005[עומד,\u0006 מוחזק, \u0005בנכסיו]\u0006 ולכן חובת ההוכחה היא על המוכר הבא להוציא ממנו.","וכן מדברי \u0003רב נחמן\u0004 על דברי \u0003רב נחמן נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 \u0003כיון\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 שמוכר לו את כל הנכסים \u0003דבי\u0004 \u0005[של בית]\u0006 \u0003בר סיסין, ומיקריא\u0004 \u0005[ונקראת]\u0006 בפי הכל \u0003\"דבי\u0004 \u0005[של בית]\u0006 \u0003בר סיסין\",\u0004 ולכן \u0003עליה דידיה רמיא לגלויי דלאו דבי\u0004 \u0005[עליו עצמו מוטל לגלות שלא של בית]\u0006 \u0003בר סיסין היא, אבל הכא\u0004 \u0005[כאן]\u0006 ב\"שכוני גואי\", \u0003לא יהא\u0004 הקונה \u0003אלא\u0004 כמי \u0003דנקיט שטרא\u0004 \u0005[שמחזיק שטר]\u0006 — \u0003מי לא אמרינן ליה\u0004 \u0005[האם אין אנו אומרים לו]:\u0006 \u0003קיים\u0004 את \u0003שטרך\u0004 בפני בית דין \u0003וקום בניכסי\u0004 \u0005[\u0006ואז \u0005תעמוד,\u0006 תחזיק \u0005בנכסים]?\u0006 ואף כאן, כיון שזכותו וחזקתו מחמת השימוש, במקום שטר היא — צריך לברר בעדים שאכן כך היה הדבר.","מסופר: \u0003ההוא דאמר ליה לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לו לחבירו]:\u0006 \u0003מאי בעית בהאי ביתא\u0004 \u0005[מה אתה מבקש,\u0006 עושה, \u0005בבית זה]?\u0006 כלומר, באיזו רשות אתה מתגורר בו, והרי הוא שלי! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מינך זבנתיה\u0004 \u0005[ממך קניתיו]\u0006 \u0003ואכלתיה שני חזקה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בשוקי בראי הואי\u0004 \u0005[בשווקים חיצוניים הייתי],\u0006 כלומר, הייתי במקומות הרחוקים ולא ידעתי שאתה יושב בבית. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא אית\u0004 \u0005[והרי יש]\u0006 \u0003לי סהדי\u0004 \u0005[עדים]\u0006 ש\u0003כל שתא הוה אתית תלתין יומי\u0004 \u0005[שנה היית בא\u0006 לכאן ל\u0005שלושים יום]\u0006 ובכל זאת לא מחית בידי באותם שלושים יום? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תלתין יומי בשוקאי הוה טרידנא\u0004 \u0005[שלושים יום\u0006 אלה \u0005בשוקי הייתי עסוק]\u0006 למכור את הסחורות שקניתי במקומות אחרים. \u0003אמר רבא:\u0004 הדין עימו, שכן \u0003עביד איניש\u0004 \u0005[עשוי אדם]\u0006 ש\u0003כל תלתין יומי טריד בשוקא\u0004 \u0005[שלושים יום\u0006 יהיה \u0005טרוד בשוק]\u0006 ולא יהיה לו זמן לברר מי משתמש בביתו.","מסופר: \u0003ההוא דאמר ליה לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לו לחבירו]:\u0006 \u0003מאי בעית בהאי ארעא\u0004 \u0005[מה אתה מבקש,\u0006 עושה, \u0005בקרקע זו]\u0006 שאתה יושב עליה? שלי היא! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מפלניא זבינתה\u0004 \u0005[מפלוני קניתיה]\u0006 ש\u0003אמר לי דזבנה מינך\u0004 \u0005[שקנה אותה ממך].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הקרקע הראשון: \u0003את לאו קא מודית\u0004 \u0005[\u0006האם \u0005אתה אינך מודה]\u0006"],["\u0003דהאי ארעא דידי\u0004 \u0005[שקרקע זו שלי]\u0006 \u0003היא ואת\u0004 \u0005[ואתה]\u0006 \u0003לא זבינתה מינאי\u0004 \u0005[קניתיה ממני]?\u0006 \u0003זיל לאו\u0004 \u0005[לך\u0006 מכאן \u0005לא]\u0006 \u0003בעל דברים דידי את\u0004 \u0005[שלי אתה]\u0006 ולך למי שמכר לך, ותבע ממנו. \u0003אמר רבא: דינא קאמר ליה\u0004 \u0005[דין אמר לו],\u0006 כלומר, הדין עימו, והוא יכול להפקיע את הקרקע.","ועוד מסופר, \u0003ההוא\u0004 \u0005[אדם אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006 \u0003מאי בעית בהאי ארעא\u0004 \u0005[מה אתה מבקש,\u0006 עושה \u0005בקרקע זו]\u0006 שהיא שלי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מפלניא זבינא\u0004 \u0005[מפלוני קניתיה]\u0006 \u0003ואכלתיה שני חזקה. אמר ליה\u0004 \u0005[לו]:\u0006 אותו \u0003פלניא גזלנא\u0004 \u0005[פלוני גזלן]\u0006 \u0003הוא\u0004 וגזלה ממני.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא אית\u0004 \u0005[והרי יש]\u0006 \u0003לי סהדי\u0004 \u0005[עדים]\u0006 \u0003דאתאי אימלכי\u0004 \u0005[שבאתי ונמלכתי,\u0006 התיעצתי\u0005]\u0006 \u0003בך ואמרת לי \"זיל זבין\"\u0004 \u0005[לך קנה]\u0006 את הקרקע<small],< small=\"\"> והרי זה מוכיח שאין הקרקע שלך! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003השני נוח לי,\u0004 כלומר, חשבתי שיהיה נוח לי להתדיין אתך, \u0003הראשון קשה הימנו\u0004 ואיני יכול להתדיין איתו, ולכן העדפתי שאתה תקנה. \u0003אמר רבא: דינא קאמר ליה\u0004 \u0005[דין אמר לו],\u0006 שאין בעצתו משום הודאה בבעלות המוכר על הקרקע.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אמר דבר זה, האם \u0003כ\u0004דעת \u0003אדמון? דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003העורר על השדה\u0004 לומר ששלו היא, ונגזלה מידו, \u0003ו\u0004נמצא שהוא עצמו \u0003חתום עליה,\u0004 על שטר המכירה שלה, \u0003בעד,\u0004 שמכרה הגזלן לאדם אחר. \u0003אדמון אומר:\u0004 יכול העורר הזה לומר: \u0003השני\u0004 הקונה את הקרקע \u0003נוח לי\u0004 שאוכל להוציא מידו את השדה ביתר קלות, ואילו \u0003הראשון קשה הימנו,\u0004 ולכן הסכמתי להיות עד באותה מכירה. \u0003וחכמים אומרים:\u0004 כיון שחתם \u0003איבד את זכותו.\u0004","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שאמרו כי משעה שחתם איבד את זכותו, \u0003התם עבד ליה\u0004 \u0005[שם\u0006 שחתם \u0005עשה לו]\u0006 \u0003מעשה, אבל הכא\u0004 \u0005[כאן]\u0006 שנתן עצה, \u0003דבורא\u0004 \u0005[דיבור\u0006 בלבד\u0005]\u0006 הוא ובכגון זה, \u0003עביד איניש דמיקרי ואמר\u0004 \u0005[עשוי אדם שיזדמן ויאמר]\u0006 ואין בכך בכדי לאבד את זכותו.","ועוד מסופר, \u0003ההוא\u0004 \u0005[אדם אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לחבירו]:\u0006 \u0003מאי בעית בהאי ארעא\u0004 \u0005[מה מבקש אתה בקרקע זו]\u0006 שהיא שלי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מפלניא זבינתה\u0004 \u0005[מפלוני קניתיה]\u0006 \u0003ואכלתיה שני חזקה. אמר ליה\u0004 \u0005[לו]:\u0006 אותו \u0003פלניא גזלנא\u0004 \u0005[פלוני גזלן]\u0006 \u0003הוא\u0004 וגזל אותה ממני. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא אית\u0004 \u0005[והרי יש]\u0006 \u0003לי סהדי דאתית באורתא\u0004 \u0005[עדים שבאת בערב]\u0006 \u0003ואמרת לי: זבנה ניהלי\u0004 \u0005[מכור אותה לי],\u0006 ואם שלך היתה מדוע לא תבעת שתחזור לך בלא לשלם עבורה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמינא איזבון דינאי\u0004 \u0005[אמרתי אקנה את דיני],\u0006 כלומר, אקנה ממך בכסף מועט, כדי שלא אזדקק לבוא לדין. \u0003אמר רבא: עביד איניש דזבין דיניה\u0004 \u0005[עשוי אדם שיקנה את דינו],\u0006 ולכן מדבריו אלה אין הוכחה שויתר על טענת הבעלות.","ומסופר עוד, \u0003ההוא\u0004 \u0005[אדם אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006 \u0003מאי בעית בהאי ארעא\u0004 \u0005[מה מבקש אתה בקרקע זו]\u0006 שהיא שלי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מפלניא זבינא\u0004 \u0005[מפלוני קניתיה]\u0006 \u0003ואכלתיה שני חזקה!\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא נקיטנא שטרא דזבני ליה מיניה הא ארבעי שני\u0004 \u0005[והרי מחזיק אני שטר שאני קניתי אותה ממנו זה ארבע שנים].\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שכשאמרתי \u0003\"שני חזקה\" תלת שני קא אמינא\u0004 \u0005[שלוש שנים אני אומר],\u0006 ושטרך קודם? \u0003שני חזקה טובא קא אמינא\u0004 \u0005[הרבה אני אומר]\u0006 ושנים רבות השתמשתי בקרקע זו. \u0003אמר רבא: עבידי אינשי דקרו לשני טובא\u0004 \u0005[עשויים אנשים שקוראים לשנים הרבה]\u0006 \u0003\"שני חזקה\".\u0004","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 אם יכול המחזיק להביא עדים ש\u0003אכלה\u0004 את השדה הזה \u0003שבע\u0004 שנים, \u0003דקדים\u0004 \u0005[שקודמת]\u0006 ה\u0003חזקה דהאי לשטרא דהך\u0004 \u0005[של זה לשטר של האחר].\u0006"],["\u0003אבל\u0004 אם ישב שם רק \u0003שית\u0004 \u0005[שש\u0006 שנים\u0005]\u0006 הרי במקרה זה כאשר מכר הבעלים הראשונים את השדה לאדם אחר בתוך שלוש השנים שישב בה המחזיק — \u0003אין לך מחאה גדולה מזו\u0004 שמחה בתוך הזמן הראוי, ואין כאן חזקה.","ומסופר על שני אנשים שהיו מתווכחים על קרקע שהחזיק אחד מהם, \u0003זה אומר:\u0004 הקרקע היתה \u0003של אבותי\u0004 וירשתיה מהם, \u0003וזה אומר: של אבותי. האי אייתי סהדי דאבהתיה\u0004 \u0005[זה הביא עדים\u0006 שהעידו כי \u0005של אבותיו]\u0006 \u0003היא, והאי אייתי סהדי\u0004 \u0005[וזה הביא עדים]\u0006 ש\u0003אכלה שני\u0004 (שנות) \u0003חזקה.\u0004","\u0003אמר רבה:\u0004 יש להאמין לזה שהחזיק בקרקע כי של אבותיו שלו היתה, שכן \u0003מה לו לשקר? אי בעי\u0004 \u0005[אם\u0006 היה \u0005רוצה\u0006 לשקר\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[היה אומר לו]:\u0006 \u0003מינך זבנתה\u0004 \u0005[ממך קניתיה]\u0006 \u0003ואכלתיה שני חזקה,\u0004 והיה זוכה בקרקע. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: \"מה לי לשקר\" במקום עדים לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006 שכיון שיש עדים שמעידים שהקרקע היתה של אבותיו של האחר, אין לבטל את עדותם על פי סברה של \"מה לי לשקר\".","ומסופר, \u0003הדר אמר ליה\u0004 \u0005[חזר\u0006 אותו מחזיק ו\u0005אמר לו\u0006 למערער\u0005]:\u0006 \u0003אין, דאבהתך\u0004 \u0005[כן, של אבותיך]\u0006 \u0003היא וזבנתה מינך\u0004 \u0005[וקניתיה ממך],\u0006 \u0003והאי דאמרי\u0004 \u0005[וזה שאמרתי]\u0006 \u0003לך\u0004 שהיא \u0003דאבהתי\u0004 \u0005[של אבותי],\u0006 כוונתי היתה \u0003דסמיך לי עלה כדאבהתי\u0004 \u0005[שאני סומך עליה כאילו\u0006 היתה \u0005של אבותי]\u0006 לפי שקניתיה והחזקתי בה כדין.","ועלתה השאלה: האם יכול אדם להיות \u0003טוען\u0004 טענה אחת \u0003וחוזר וטוען\u0004 טענה אחרת להסביר את דבריו הראשונים, \u0003או אין טוען וחוזר וטוען? עולא אמר: טוען וחוזר וטוען. נהרדעי אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אינו טוען וחוזר וטוען.\u0004","ומעירים: \u0003ומודי\u0004 \u0005[ומודה]\u0006 \u0003עולא היכא\u0004 \u0005[היכן]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בתחילה \u0003\"של אבותי\u0004 היתה \u0003ולא של אבותיך\",\u0004 ש\u0003אינו טוען וחוזר וטוען,\u0004 שהרי טענתו השניה היא הכחשה מוחלטת לטענתו הקודמת. ורק אם טען דברים שאינם סותרים לגמרי את דבריו הראשונים, יכול לחזור ולטעון טענה אחרת בנוסף על הראשונה. \u0003ו\u0004עוד מודה עולא \u0003היכא דהוה קאי בי דינא\u0004 \u0005[היכן שהיה עומד בבית הדין]\u0006 \u0003ולא טען\u0004 טענה חדשה, \u0003ואתא מאבראי\u0004 \u0005[ובא\u0006 אחר כך \u0005מבחוץ]\u0006 \u0003וטען\u0004 — שאף במקרה זה \u0003אינו חוזר וטוען.\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003טענתיה אגמריה\u0004 \u0005[טענותיו\u0006 אלה האחרונות \u0005לימד אותו\u0006 מישהו\u0005]\u0006 ואין זו טענת אמת.","\u0003ו\u0004מצד שני, \u0003מודו\u0004 \u0005[מודים]\u0006 חכמי \u0003נהרדעי היכא דאמר ליה\u0004 \u0005[היכן שאומר לו]\u0006 כהסבר לדבריו הראשונים: כשאמרתי לך \"של אבותי\" כוונתי היתה — \u0003של אבותי שלקחוה מאבותיך,\u0004 ש\u0003חוזר וטוען\u0004 ומאמינים לו. \u0003ו\u0004כן מודים חכמי נהרדעא \u0003היכא דאישתעי מילי אבראי\u0004 \u0005[היכן שסיפר דברים מחוץ]\u0006 לבית הדין \u0003ולא טען, ואתא לבי דינא\u0004 \u0005[ובא לבית הדין]\u0006 \u0003וטען,\u0004 שבמקרה כזה \u0003חוזר וטוען. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003עביד איניש\u0004 \u0005[עשוי אדם]\u0006 ש\u0003לא מגלי טענתיה\u0004 \u0005[מגלה\u0006 את \u0005טענותיו]\u0006 \u0003אלא לבי דינא\u0004 \u0005[לבית דין]\u0006 ולא לאחרים.","\u0003אמר אמימר: אנא\u0004 \u0005[אני]\u0006 מ\u0003נהרדעא אנא\u0004 \u0005[אני]\u0006 \u0003וסבירא לי\u0004 \u0005[וסבור אני]\u0006 כדעת עולא ש\u0003טוען וחוזר וטוען.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]\u0006 ש\u0003טוען וחוזר וטוען.\u0004","מקרה אחר, \u0003זה אומר:\u0004 קרקע זו \u0003של אבותי\u0004 היא, וירשתיה מהם, \u0003וזה אומר: של אבותי. האי אייתי סהדי דאבהתיה\u0004 \u0005[זה הביא עדים\u0006 שהיתה \u0005של אבותיו]\u0006 \u0003ואכלה שני חזקה, והאי אייתי סהדי\u0004 \u0005[וזה הביא עדים]\u0006 ש\u0003אכלה שני חזקה\u0004 באותן שנים עצמן.","\u0003אמר רב נחמן:\u0004 כיון שיש עדים לענין חזקה לשני הצדדים והם מכחישים זה את זה \u0003אוקי\u0004 \u0005[העמד]\u0006 \u0003אכילה לבהדי\u0004 \u0005[כנגד]\u0006 \u0003אכילה\u0004 ובטל את שתי העדויות הללו, לפי שהן סותרות, \u0003ואוקי ארעא בחזקת אבהתא\u0004 \u0005[והעמד\u0006 את \u0005הקרקע בחזקת האבות]\u0006 לפי העדות שהיתה של אבותיו של אחד מהם, שעל כל פנים טענה זו לא נסתרה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 הלא \u0003הא\u0004 \u0005[זו]\u0006 \u0003עדות מוכחשת היא,\u0004 שברור שאחת מכתות העדים העידה שקר, ואי אפשר לסמוך על עדות מפוקפקת כזו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003נהי דאיתכחש\u0004 \u0005[אמנם\u0006 נכון \u0005שהוכחשה\u0006 העדות\u0005]\u0006 \u0003ב\u0004ענין \u0003אכילתה\u0004 של הקרקע,"],["\u0003באבהתא מי אתכחש\u0004 \u0005[באבות האם הוכחש]?\u0006 הרי עדות זו קיימת, והכל מודים בה.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003רבא ורב נחמן בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003רב הונא ורב חסדא קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005]!\u0006","\u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בשאלה הבאה: \u0003שתי כתי עדים המכחישות זו את זו; אמר רב הונא: זו באה בפני עצמה ומעידה\u0004 בעדות אחרת, \u0003וזו באה בפני עצמה ומעידה\u0004 בעדות אחרת, שאינן נעשות בכך פסולות לעדות על אף שאחת מהן בודאי שיקרה. \u0003ורב חסדא אמר: בהדי סהדי שקרי\u0004 \u0005[ביחד עם עדים שקרנים]\u0006 \u0003למה לי?\u0004 שהרי ברור שכת אחת משקרת, וכיון שיש ספק לגבי כל אחת מהן שמא הם שקרנים, מדוע נזדקק להם? \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 ש\u0003רב נחמן\u0004 ש\u0003אמר כרב הונא, ורבא\u0004 אומר \u0003כרב חסדא?\u0004","ואומרים: \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003רב חסדא\u0004 שפסל את העדים גם לעדות אחרת — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שבוודאי אין סומכים על מקצת העדות שחלק ממנה הוכחש. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 בשיטת אחד משני אמוראים אלה — הרי זה \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003רב הונא. רב נחמן\u0004 שקיבל את העדות על חזקת האבות — סבור \u0003כרב הונא\u0004 ממש, שכל אחת מהן כשרה לעדות אחרת. \u0003ורבא?\u0004 הוא יכול לומר: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רב הונא אלא\u0004 להכשירה \u0003לעדות אחרת, אבל לאותה עדות\u0004 — \u0003לא.\u0004 וכאן הרי מעידים על דבר אחד — על הזכות לאותה קרקע. וממשיכים בסיפור אותו מעשה שדנו בו.","\u0003הדר אייתי סהדי דאבהתיה\u0004 \u0005[חזר\u0006 זה שהיתה לו עדות על חזקה בלבד ו\u0005הביא עדים\u0006 כי \u0005של אבותיו]\u0006 \u0003היא,\u0004 ונמצא שלשניהם עדות שווה על אותה קרקע — הן שהיתה של אבותיהם, והן שהחזיקו בה. \u0003אמר רב נחמן: אנן אחתיניה אנן מסקינן ליה\u0004 \u0005[אנו הורדנו אותו\u0006 את מי שהביא עדים שהיתה של אבותיו, לשדה, \u0005אנו\u0006 גם \u0005מעלים\u0006 ומוציאים \u0005אותו]\u0006 ממנה, ו\u0003לזילותא דבי דינא לא חיישינן\u0004 \u0005[לזילות בית דין אין אנו חוששים],\u0006 ואין אומרים שיבואו הבריות לומר שבית הדין אינו יציב, והופך את דבריו.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רבא\u0004 על סברה זו שאין חוששים לזילות בית הדין, \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' זעירא,\u0004 ממה ששנינו בברייתא: \u0003שנים אומרים \"מת\u0004 בעלה של אשה במקום אחר \u0003\",\u0004 \u0003ושנים אומרים \"לא מת\"; שנים אומרים \"נתגרשה\u0004 האשה \u0003\",\u0004 \u0003ושנים אומרים \"לא נתגרשה\"\u0004 — \u0003הרי זו לא תנשא\u0004 לאיש אחר, שספק הוא, \u0003ואם נשאת\u0004 — \u0003לא תצא\u0004 ממנו. \u0003ר' מנחם בר' יוסי אומר:\u0004 אף אם נישאת \u0003תצא.\u0004","\u0003אמר ר' מנחם בר' יוסי: אימתי אני אומר תצא?\u0004 — \u0003בזמן שבאו עדים\u0004 המכחישים את מות הבעל או הגירושין, \u0003ואחר כך נשאת,\u0004 שכשנישאה ידעה שהיא נכנסת לספק, \u0003אבל\u0004 אם קודם \u0003נשאת ו\u0004רק \u0003אחר כך באו עדים\u0004 — \u0003הרי זו לא תצא.\u0004 משמע שאנו חוששים לכבוד בית הדין שהתירה להינשא, ואין מוציאים אותה מבעלה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרבא: \u0003אנא סברי למעבד עובדא\u0004 \u0005[אני חשבתי לעשות מעשה\u0006 בפועל\u0005],\u0006 ולהוציא מן הקרקע את מי שנתנוה לו, \u0003השתא דאותיבתן את\u0004 \u0005[עכשיו שהקשית אתה לי]\u0006 \u0003ואותבן\u0004 \u0005[והקשה עלי]\u0006 גם \u0003רב המנונא בסוריא\u0004 והוכחתם שיש לחשוש לזילות בית הדין — \u0003לא עבדינן\u0004 \u0005[אין אני עושה]\u0006 \u0003בה עובדא\u0004 \u0005[מעשה].\u0006","לבסוף \u0003נפק עבד עובדא\u0004 \u0005[יצא\u0006 רב נחמן ו\u0005עשה מעשה]\u0006 כפי שהחליט מתחילה. \u0003מאן דחזא סבר טעותא היא בידיה\u0004 \u0005[מי שראה סבר\u0006 ש\u0005טעות היתה בידו],\u0006 שטעה ושכח מה שאמר, \u0003ולא היא\u0004 (אין הדבר כך), \u0003אלא משום דתליא באשלי רברבי\u0004 \u0005[שתלוי\u0006 הדבר \u0005באילנות גדולים],\u0006 כלומר, רב נחמן סמך על חכמים חשובים הסבורים כמותו.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: אין מעלין לכהונה\u0004 להחשיב אדם לכהן, \u0003על פי עד אחד. אמר ר' אלעזר: אימתי\u0004 אומרים שאין מעלים על פי אחד — \u0003במקום שיש עוררין\u0004 על כהונתו (כגון שאומרים עליו שהוא בן כהן שנשא גרושה) \u0003אבל במקום שאין עוררין\u0004 על כהונתו — \u0003מעלין\u0004 אותו \u0003לכהונה על פי עד אחד. רבן שמעון בן גמליאל אומר משום\u0004 (בשם) \u0003ר' שמעון בן הסגן: מעלין לכהונה על פי עד אחד.\u0004","ותוהים: הלא דעת \u0003רבן שמעון בן גמליאל היינו\u0004 \u0005[זו היא]\u0006 דעת \u0003ר' אלעזר,\u0004 ומה בא להוסיף? \u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 כי ביחס ל\u0003ערער חד איכא בינייהו\u0004 \u0005[מערער אחד יש ביניהם\u0006 הבדל\u0005],\u0006 ותפרש כי \u0003ר' אלעזר סבר\u0004 \u0005[סבור]:\u0006 אין מעלים לכהונה על פי עד אחד גם במקום שיש רק \u0003ערער חד\u0004 \u0005[אחד]\u0006 שמערער על כהונתו של אותו אדם,"],["\u0003ורבן שמעון בן גמליאל סבר: ערער\u0004 שאין עד אחד מועיל כנגדו להכשיר — הוא דווקא זה של \u0003תרי\u0004 \u0005[שנים],\u0006 אבל אם יש רק מערער אחד יכול עד אחד להכשיר, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: דברי הכל אין ערער פחות משנים,\u0004 וערעור של עד אחד אינו נחשב כלל!","\u0003אלא\u0004 יש לומר שלדעת הכל מדובר ב\u0003ערער תרי\u0004 \u0005[\u0006של \u0005שנים],\u0006 \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]?\u0006 — במקרה \u0003כגון דמחזקינן ליה באבוה דהאי\u0004 \u0005[שמוחזק לנו באביו של זה]\u0006 ש\u0003כהן הוא, ונפק עליה קלא\u0004 \u0005[ויצא עליו קול,\u0006 שמועה\u0005]\u0006 על הבן ש\u0003בן גרושה ובן חלוצה הוא,\u0004 והרי הוא חלל, ולכן אף שהוא בן כהן, מכל מקום הוא עצמו אינו כהן, \u0003ואחתיניה\u0004 \u0005[והורדנו אותו]\u0006 מן הכהונה, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003עד אחד ואמר\u0004 ש\u0003כהן הוא, ואסקיניה\u0004 \u0005[והעלינו אותו]\u0006 לכהונה,","\u0003ואתו בי תרי ואמרי\u0004 \u0005[ו\u0006אחר כך \u0005באו שניים ואמרו]\u0006 ש\u0003בן גרושה ו\u0004בן \u0003חלוצה הוא, ואחתיניה\u0004 \u0005[ו\u0006שוב \u0005הורדנו אותו],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003עד אחד\u0004 נוסף \u0003ואמר\u0004 ש\u0003כהן הוא. ודכולי עלמא\u0004 \u0005[ולדעת הכל]\u0006 \u0003מצטרפין\u0004 שנים שהעידו כל אחד בנפרד ל\u0003עדות\u0004 אחת, ולכן מן הדין היה כשר לכהונה, שהרי יש (בצירוף) שני עדים המכשירים אותו, הראשון והאחרון.","\u0003והכא במיחש לזילותא דבי דינא קא מיפלגי\u0004 \u0005[וכאן בחשש לזילות בית דין הם חולקים],\u0006 ש\u0003ר' אלעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003כיון דאחתיניה לא מסקינן ליה\u0004 \u0005[שהורדנו אותו\u0006 לכן \u0005אין מעלים אותו],\u0006 שכן לדעתו \u0003חיישינן לזילותא דבי דינא\u0004 \u0005[חוששים אנו לזילות בית הדין],\u0006 שהרי נראה שבית הדין משנים כל פעם את פסיקתם. \u0003ורבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003אנן אחתיניה ואנן מסקינן ליה\u0004 \u0005[אנו הורדנו אותו ואנו מעלים אותו],\u0006 \u0003ולזילותא דבי דינא לא חיישינן\u0004 \u0005[ולזילות בית דין אין אנו חוששים].\u0006 ורב נחמן, שלא חשש לעיל לזילות בית הדין, סבור כדעת רבן שמעון בן גמליאל.","ולעצם הסבר זה של המחלוקת \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: אי הכי\u0004 \u0005[אם כך],\u0006 אם זהו טעם המחלוקת, \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 במקרה שהיה בסוף \u0003חד\u0004 \u0005[\u0006עד \u0005אחד]\u0006 שהכשיר, נחלקו? \u0003אפילו בתרי נמי\u0004 \u0005[בשני\u0006 עדים \u0005גם כן]\u0006 אם באו בסוף להכשירו, גם אז קיים החשש לזילות בית הדין! \u0003אלא אמר רב אשי:\u0004 כך צריך להבין, \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003לא חיישינן לזילותא דבי דינא\u0004 \u0005[אין אנו חוששים לזילות בית הדין],\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003בלצרף עדות קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 האם מצטרפות עדויותיהם של העדים הבודדים. \u0003ובפלוגתא דהני תנאי\u0004 \u0005[ובמחלוקת של התנאים הללו]\u0006 נחלקו הם,","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לעולם אין עדותן\u0004 של עדים \u0003מצטרפת עד שיראו שניהן\u0004 את המאורע \u0003כאחד. ר' יהושע בן קרחה אומר: אפילו\u0004 אם באו \u0003בזה אחר זה.\u0004 ומחלוקת אחרת בצירוף עדים: \u0003אין עדותן\u0004 של שנים, אף שראו כאחד, \u0003מתקיימת בבית דין עד שיעידו שניהם כאחד.\u0004 ואילו \u0003ר' נתן אומר:\u0004 אפילו \u0003שומעין דבריו של\u0004 עד \u0003זה היום, ולכשיבא חבירו למחר\u0004 — \u0003שומעין דבריו.\u0004 ושתי העדויות מצטרפות, ובמחלוקת זו שבין חכמים ור' נתן נחלקו ר' אלעזר ורבן שמעון בן גמליאל.","ועוד בענייני קרקעות, \u0003ההוא דאמר לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לחבירו]:\u0006 \u0003מאי בעית בהאי ארעא\u0004 \u0005[מה אתה מבקש בקרקע זו]\u0006 שהיא שלי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מינך זבינתה והא שטרא\u0004 \u0005[ממך קניתיה והרי השטר].\u0006"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 המערער: \u0003שטרא זייפא\u0004 \u0005[שטר מזוייף]\u0006 \u0003הוא;\u0004 \u0003גחין לחיש ליה\u0004 \u0005[התכופף\u0006 בעל השטר \u0005לחש לו]\u0006 \u0003לרבה: אין, שטרא זייפא\u0004 \u0005[כן, שטר מזוייף]\u0006 \u0003הוא, מיהו שטרא מעליא הוה\u0004 \u0005[\u0006ו\u0005אולם שטר טוב היה]\u0006 \u0003לי\u0004 \u0003ואירכס\u0004 \u0005[ואבד],\u0006 \u0003ואמינא\u0004 \u0005[ואמרתי]:\u0006 \u0003אינקיט האי בידאי\u0004 \u0005[אחזיק את זה\u0006 שיהא בינתים \u0005בידי]\u0006 שטר \u0003כל דהו\u0004 \u0005[שהוא],\u0006 עד שאמצא את השטר.","\u0003אמר רבה: מה לו לשקר? אי בעי אמר ליה שטרא מעליא\u0004 \u0005[אם היה רוצה\u0006 לשקר \u0005היה אומר לו\u0006 ש\u0005שטר טוב]\u0006 \u0003הוא,\u0004 ולא היינו חושדים בדבר. ואם כן, יש להשאיר את הקרקע בידיו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף:\u0004 סוף סוף \u0003אמאי סמכת\u0004 \u0005[על מה אתה סומך]?\u0006 \u0003אהאי שטרא\u0004 \u0005[על שטר זה],\u0006 ואולם \u0003האי שטרא חספא בעלמא\u0004 \u0005[שטר זה חרס בלבד]\u0006 \u0003הוא\u0004 ואינו שווה דבר, שהרי הודה המלוה על כך. ואם כן, אין לו ראיה כלל לחזקתו בקרקע.","מעין זה מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר לחבריה\u0004 \u0005[לחבירו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי מאה זוזי דמסיקנא\u0004 \u0005[זוזים שאני נושה]\u0006 \u0003בך, והא שטרא\u0004 \u0005[והרי השטר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הנתבע: \u0003שטרא זייפא\u0004 \u0005[שטר מזוייף]\u0006 \u0003הוא. גחין לחיש ליה\u0004 \u0005[התכופך\u0006 בעל השטר ו\u0005לחש לו]\u0006 \u0003לרבא: אין, שטרא זייפא\u0004 \u0005[כן, שטר מזוייף]\u0006 הוא \u0003מיהו שטרא מעליא הוה\u0004 \u0005[\u0006ו\u0005אולם שטר טוב היה]\u0006 \u0003לי ואירכס\u0004 \u0005[ואבד],\u0006 \u0003ואמינא\u0004 \u0005[ואמרתי]:\u0006 \u0003אינקיט האי בידאי\u0004 \u0005[אחזיק את זה בידי]\u0006 בינתים שיהיה לי שטר \u0003כל דהו\u0004 \u0005[שהוא],\u0006","\u0003אמר רבה: מה לו לשקר? אי בעי אמר ליה שטרא מעליא\u0004 \u0005[אם היה רוצה\u0006 לשקר \u0005היה אומר לו\u0006 ש\u0005שטר טוב]\u0006 \u0003הוא,\u0004 והיה גובה בו, ואף עכשיו נאמין לו ונגבה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: אמאי קא סמכת\u0004 \u0005[על מה אתה סומך]?\u0006 \u0003אהאי שטרא\u0004 \u0005[על שטר זה]\u0006 — \u0003האי שטרא חספא בעלמא\u0004 \u0005[שטר זה חרס בלבד]\u0006 \u0003הוא,\u0004 שהרי בעליו מודה שהוא מזוייף!","\u0003אמר רב אידי בר אבין: הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רבה בארעא\u0004 \u0005[בקרקע],\u0006 \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב יוסף בזוזי\u0004 \u0005[בכסף].\u0006 ומסבירים: \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרבה\u0004 שסומכים על השטר \u0003בארעא\u0004 \u0005[בקרקע],\u0006 משום שאנו אומרים \u0003דהיכא דקיימא ארעא תיקום\u0004 \u0005[שהיכן שעומדת הקרקע תעמוד],\u0006 ובפועל הרי היא מוחזקת בידי בעל השטר. \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב יוסף\u0004 שאין סומכים על השטר \u0003בזוזי\u0004 \u0005[בכספים]\u0006 משום אותה סיבה עצמה — \u0003דהיכא דקיימי זוזי לוקמי\u0004 \u0005[שהיכן שנמצאים הכספים שיימצאו\u0006 הלאה\u0005],\u0006","והם עתה בידי הלווה, ואינו צריך לשלם. ומסופר על מקרה דומה: \u0003ההוא ערבא דאמר ליה\u0004 \u0005[ערב אחד שאמר לו]\u0006 \u0003ללוה: הב\u0004 \u0005[תן]\u0006 \u0003לי מאה זוזי\u0004 \u0005[זוזים]\u0006 ש\u0003פרעתי למלוה עילוך\u0004 \u0005[עליך,\u0006 בשבילך\u0005],\u0006 \u0003והא שטרא\u0004 \u0005[והרי שטר\u0006 החוב שלך\u0005]\u0006 שקיבלתי מידו לאחר שפרעתי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הלווה: \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003פרעתיך\u0004 את החוב הזה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 הערב: \u0003לאו הדרת שקלתינהו מינאי\u0004 \u0005[האם לא חזרת\u0006 ו\u0005לקחת אותם\u0006 את המעות \u0005ממני]?\u0006","\u0003שלחה\u0004 \u0003רב אידי בר אבין\u0004 את השאלה הזו \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003אביי: כי האי גוונא מאי\u0004 \u0005[כגון זה מהו]?\u0006 \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי תיבעי ליה\u0004 \u0005[מה תישאל,\u0006 תסתפק \u0005לו]?\u0006 \u0003הא איהו\u0004 \u0005[הרי הוא\u0006 עצמו\u0005]\u0006 זה ש\u0003אמר\u0004 כי \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רבה בארעא\u0004 \u0005[בקרקע],\u0006 \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב יוסף בזוזי\u0004 \u0005[בכספים],\u0006 וטעמו: \u0003דהיכא דאוקמו זוזי לוקמו\u0004 \u0005[שהיכן שנמצאים הכספים שיימצאו\u0006 הלאה\u0005].\u0006 ואף כאן ישאר הכסף בידי הלווה!","ומעירים: \u0003והני מילי דאמר ליה\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא באופן \u0005שאומר לו]\u0006 הערב: הרי \u0003הדרת אוזפתינהו מינאי\u0004 \u0005[אתה חזרת\u0006 ו\u0005לוית אותה ממני],\u0006 ואם כן הוא בא לטעון על חוב חדש, בשטר שהוא עצמו מודה בחוסר תקפותו. \u0003אבל\u0004 אם \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הדרתינהו ניהלך\u0004 \u0005[החזרתי לך]\u0006 את הכספים הללו שפרעת לי \u0003מחמת דהוו שייפי וסומקי\u0004 \u0005[שהיו משופשפים ואדומים]\u0006 ורציתי לקבל מטבעות טובים יותר, ובעצם לא קיבלתי ממך עדיין את הסכום שפרעתי עבורך, במקרה כזה \u0003אכתי איתיה לשעבודא דשטרא\u0004 \u0005[עדיין נמצא שעבוד השטר\u0006 הראשון\u0005]\u0006 בתוקפו, ומשום כך צריך הנתבע לשלם, שעדיין לא נמחל חובו.","מסופר: \u0003רבא בר שרשום נפק עליה קלא דקא אכיל ארעא דיתמי\u0004 \u0005[יצא עליו קול שהוא אוכל,\u0006 נהנה, \u0005מקרקע של יתומים],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אימא\u0004 \u0005[אמור]\u0006 \u0003לי איזי\u0004 \u0005[ידידי],\u0006 \u0003גופא דעובדא היכי הוה\u0004 \u0005[גוף המעשה איך היה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ארעא במשכונתא הוה נקיטנא מאבוהון דיתמי\u0004 \u0005[\u0006את \u0005הקרקע במשכון הייתי מחזיק מאבי היתומים],\u0006 \u0003והוה\u0004 \u0005[והיו]\u0006 \u0003לי\u0004"],["\u0003זוזי אחריני גביה\u0004 \u0005[זוזים,\u0006 דינרים, \u0005אחרים אצלו]\u0006 שהיה חייב לי, \u0003ואכלתה\u0004 \u0005[ואכלתיה]\u0006 את הקרקע הזו במשך \u0003שני\u0004 \u0005[שנות]\u0006 ה\u0003משכנתא,\u0004","\u0003אמינא\u0004 \u0005[אמרתי]\u0006 לעצמי: \u0003אי מהדרנא לה ארעא ליתמי\u0004 \u0005[אם אחזיר את הקרקע ליתומים]\u0006 \u0003ואמינא דאית\u0004 \u0005[ואומר שיש]\u0006 \u0003לי זוזי אחריני גבי דאבוכון\u0004 \u0005[זוזים אחרים אצל אביכם],\u0006 הלא \u0003אמור רבנן\u0004 \u0005[אמרו חכמים]:\u0006 \u0003הבא ליפרע מנכסי יתומים\u0004 — \u0003לא יפרע אלא בשבועה,\u0004 ואצטרך להישבע, ואין רצוני להישבע. \u0003אלא אכבשיה\u0004 \u0005[אטמינו,\u0006 אסתיר\u0005]\u0006 את \u0003שטר משכנתא ו\u0004בינתיים \u0003אוכלה,\u0004 אוכל מן השדה \u0003שיעור זוזי\u0004 \u0005[הזוזים]\u0006 שחייבים לי, \u0003דמיגו דאי בעינא אמינא\u0004 \u0005[שמתוך שאם אני רוצה\u0006 אני יכול \u0005לומר]\u0006 שקרקע זו \u0003לקוחה\u0004 (קנויה) \u0003היא בידי,\u0004 שהרי החזקתי בקרקע זמן מספיק לחזקה, ואז \u0003מהימנא\u0004 \u0005[מהימן אני],\u0006 ולכן גם \u0003כי אמינא דאית\u0004 \u0005[כאשר אומר שיש]\u0006 \u0003לי זוזי גבייכו\u0004 \u0005[זוזים אצלכם]\u0006 — \u0003מהימננא\u0004 \u0005[\u0006\u0005אהיה נאמן].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003\"לקוחה בידי\" לא מצית אמרת\u0004 \u0005[אינך יכול לומר],\u0006 \u0003דהא איכא עלה קלא דארעא דיתמי\u0004 \u0005[שהרי יש עליה קול שקרקע של יתומים]\u0006 \u0003היא,\u0004 ולכן אין בידך טענת \"מיגו\", מכוחה תוכל לגבות ממנה. \u0003אלא זיל אהדרה ניהלייהו\u0004 \u0005[לך החזר אותה\u0006 את הקרקע \u0005להם],\u0006 \u0003וכי גדלי יתמי אשתעי דינא בהדייהו\u0004 \u0005[וכאשר יגדלו היתומים תבוא בדין איתם]\u0006 ותבע את הכסף.","ועוד מסופר: \u0003קריביה\u0004 \u0005[קרובו]\u0006 של \u0003רב אידי בר אבין שכיב ושבק דיקלא\u0004 \u0005[מת והניח דקל],\u0006 ואחד מקרובי משפחתו החזיק בדקל. \u0003רב אידי בר אבין אמר: אנא קריבנא טפי\u0004 \u0005[אני קרוב יותר]\u0006 לאותו אדם, ואני הוא היורש אותו, \u0003וההוא גברא\u0004 \u0005[ואותו אדם]\u0006 \u0003אמר: אנא קריבנא טפי\u0004 \u0005[אני קרוב יותר].\u0006 \u0003לסוף אודי ליה דאיהו קריב טפי\u0004 \u0005[לבסוף הודה לו\u0006 אותו אדם \u0005שהוא\u0006 רב אידי \u0005קרוב יותר],\u0006 \u0003אוקמה\u0004 \u0005[העמיד]\u0006 \u0003רב חסדא\u0004 את הדקל \u0003בידיה\u0004 \u0005[בידיו]\u0006 של רב אידי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אידי: \u0003ליהדר\u0004 \u0005[שיחזיר]\u0006 \u0003לי פירי\u0004 \u0005[\u0006את \u0005הפירות]\u0006 ש\u0003אכל\u0004 מן הדקל שלא כדין \u0003מההוא יומא\u0004 \u0005[מאותו יום]\u0006 \u0003עד השתא\u0004 \u0005[עכשיו].\u0006 \u0003אמר\u0004 לו רב חסדא: אתה \u0003זה הוא שאומרים עליו\u0004 ש\u0003אדם גדול הוא? אמאן קא סמיך מר\u0004 \u0005[על מי סומך אדוני]\u0006 שאתה תובע את הדקל? \u0003אהאי\u0004 \u0005[על\u0006 אדם \u0005זה],\u0006 \u0003הא קאמר\u0004 \u0005[הרי הוא\u0006 היה \u0005אומר]\u0006 משך כל זמן זה: שלי הוא, \u0003דאנא מקרבנא טפי\u0004 \u0005[שאני קרוב יותר],\u0006 וכל עוד לא הודה מעצמו היה הדקל שלו. ומעירים: \u0003אביי ורבא לא סבירא להו הא\u0004 \u0005[סברו\u0006 כפסק \u0005זה]\u0006 של \u0003רב חסדא,\u0004"],["והם סברו כי \u0003כיון דאודי\u0004 \u0005[שהודה]\u0006 — \u0003אודי\u0004 \u0005[\u0006\u0005הודה]\u0006 ועל ידי הודאתו בטלו טענותיו שמתחילה, ועליו להחזיר את הפירות.","ועוד מקרה בשניים שהתווכחו על קרקע, \u0003זה אומר \"של אבותי\u0004 הקרקע וירשתיה מהם \u0003\"\u0004\u0003וזה אומר \"של אבותי\u0004 ושלי היא \u0003\",\u0004 \u0003האי אייתי סהדי דאבהתיה\u0004 \u0005[זה הביא עדים ש\u0006הקרקע \u0005של אבותיו]\u0006 \u0003הוא, והאי אייתי סהדי\u0004 \u0005[וזה הביא עדים]\u0006 ש\u0003אכל\u0004 אותה \u0003שני חזקה,\u0004","\u0003אמר רב חסדא:\u0004 זה שהביא עדים שהחזיק הקרקע, \u0003מה לו לשקר\u0004 בטענה שהיא של אבותיו? שכן \u0003אי בעי אמר ליה\u0004 \u0005[אם היה רוצה\u0006 לשקר \u0005היה אומר לו]:\u0006 \u0003מינך זבינתה\u0004 \u0005[ממך קניתיה]\u0006 \u0003ואכלתיה שני חזקה.\u0004 ומעירים: \u0003אביי ורבא לא סבירא להו הא\u0004 \u0005[סבורים הם\u0006 כפסק \u0005זה]\u0006 של \u0003רב חסדא,\u0004 כי לדעתם את השיקול של \u0003\"מה לי לשקר\" במקום\u0004 שיש \u0003עדים לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 והרי יש לשני עדים שהקרקע של אבותיו היתה.","ועוד מקרה, \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006 \u0003מאי בעית בהאי ארעא\u0004 \u0005[מה\u0006 \u0005רצונך,\u0006 מעשיך \u0005בקרקע זו]?\u0006 שלי היא! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מינך זבני\u0004 \u0005[ממך קניתי\u0006 אותה\u0005]\u0006 \u0003ואכלתיה\u0004 כבר \u0003שני חזקה,\u0004 וצריך היה להוכיח את חזקתו, \u0003אזל אייתי סהדי\u0004 \u0005[הלך\u0006 אותו אדם ו\u0005הביא עדים]\u0006 ש\u0003אכלה תרתי שני\u0004 \u0005[שתי שנים],\u0006 ולא מצא עדים על השנה השלישית. \u0003אמר רב נחמן:\u0004 במקרה כזה, כיון שלא אומתה טענתו, \u0003הדרא ארעא והדרי פירי\u0004 \u0005[חוזרת הקרקע\u0006 לבעליה \u0005וחוזרים\u0006 גם \u0005הפירות]\u0006 שאכל במשך הזמן הזה.","\u0003אמר רב זביד: אם טען ואמר \"לפירות ירדתי\"\u0004 שאותו אדם טוען ואומר שקנה את פירותיה של קרקע זו, בלא לקנות את השדה, הרי במקרה זה היה \u0003נאמן.\u0004 \u0003לאו מי אמר\u0004 \u0005[האם לא אמר]\u0006 \u0003רב יהודה: האי מאן דנקיט מגלא ותובליא\u0004 \u0005[מי שמחזיק\u0006 בידו \u0005מגל וחבל],\u0006 \u0003ואמר\u0004 \u0005[ואומר]:\u0006 \u0003איזיל איגדריה לדיקלא דפלניא דזבניה ניהלי\u0004 \u0005[אלך\u0006 ו\u0005אגדור,\u0006 אקטוף, \u0005את\u0006 פירות \u0005הדקל של פלוני שמכר אותו לי]\u0006 — \u0003מהימן\u0004 \u0005[נאמן]\u0006 שהדקל שלו. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003לא חציף איניש דגזר דיקלא דלאו דיליה\u0004 \u0005[שאין אדם מתחצף שגודר דקל שאינו שלו],\u0006 \u0003הכא נמי לא חציף איניש למיכל פירי דלאו דיליה\u0004 \u0005[כאן גם כן אין אדם חצוף לאכול פירות שאינם שלו].\u0006","ומקשים: \u0003אי הכי, ארעא נמי\u0004 \u0005[אם כך,\u0006 שאין חושדים שהוא משקר, \u0005הקרקע גם כן]\u0006 תישאר ברשותו! ומשיבים: \u0003ארעא, אמרינן ליה\u0004 \u0005[\u0006לגבי \u0005הקרקע אומרים אנו לו]:\u0006 \u0003אחוי\u0004 \u0005[הראה]\u0006 את \u0003שטרך\u0004 להוכיח שקנית. ומקשים: \u0003אי הכי, פירי נמי\u0004 \u0005[אם כך,\u0006 לגבי \u0005פירות גם כן]\u0006 שיביא שטר מכירה שהיתה לו זכות לפירות הללו! ומשיבים: \u0003שטרא לפירי לא עבדי אינשי\u0004 \u0005[שטר לפירות\u0006 בלבד \u0005אין אנשים עושים]\u0006 ויכול לטעון שהיה ביניהם הסכם בעל פה למכירת הפירות.","ועוד מקרה, \u0003ההוא דאמר לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לחבירו]:\u0006 \u0003מאי בעית בהאי ארעא\u0004 \u0005[מה\u0006 \u0005רצונך,\u0006 מעשיך \u0005בקרקע זו\u0006 שהיא שלי\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מינך זבנית\u0004 \u0005[ממך קניתי]\u0006 את הקרקע \u0003ואכלתיה שני חזקה. אייתי חד סהדא דאכלה תלת שני\u0004 \u0005[הביא עד אחד שאכל אותה שלוש שנים],\u0006 \u0003סבור רבנן קמיה\u0004 \u0005[סבורים\u0006 היו \u0005החכמים\u0006 שישבו \u0005לפני]\u0006 \u0003אביי למימר\u0004 \u0005[לומר]:\u0006 \u0003היינו נסכא\u0004 \u0005[זהו\u0006 העיקרון של \u0005חתיכת הכסף]\u0006 של \u0003ר' אבא.\u0004 ומהו אותו ענין?","\u0003דההוא גברא דחטף נסכא מחבריה\u0004 \u0005[אדם אחד שחטף גוש כסף מחבירו].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003ר' אמי. הוה יתיב\u0004 \u0005[והיה יושב]\u0006 \u0003ר' אבא קמיה\u0004 \u0005[לפניו].\u0006 \u0003אייתי חד סהדא דמיחטף חטפא מיניה\u0004 \u0005[הביא\u0006 בעל גוש הכסף \u0005עד אחד ש\u0006אכן הלה \u0005חטף ממנו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 החוטף: \u0003אין, חטפי ודידי\u0004 \u0003חטפי\u0004 \u0005[כן, חטפתי ו\u0006אולם את \u0005שלי חטפתי],\u0006 ועל כך \u0003אמר ר' אמי:\u0004"],["\u0003היכי נידיינוה דייני להאי דינא\u0004 \u0005[איך ידונו הדיינים דין זה]\u0006 שיש בו צדדים סותרים? אם תאמר \u0003לישלם\u0004 \u0005[שישלם]\u0006 מה שחטף, הלא \u0003ליכא תרי סהדי\u0004 \u0005[אין שני עדים]\u0006 המעידים על כך! \u0003ליפטריה\u0004 \u0005[לפטור אותו]\u0006 מן הדין לגמרי, שהרי הוא טוען ששלו חטף — הרי \u0003איכא חד סהדא\u0004 \u0005[יש עד אחד]\u0006 שהעיד שחטף! אם תאמר: \u0003לישתבע\u0004 \u0005[שישבע]\u0006 שלא חטף, כמו שנשבעים כנגד טענת עד אחד — \u0003הא אמר מיחטף חטפה\u0004 \u0005[הרי\u0006 הוא \u0005אומר\u0006 ש\u0005חטף אותה],\u0006 \u0003וכיון\u0004 ש\u0003אמר\u0004 ש\u0003חטפה\u0004 — \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003כגזלן,\u0004 ופסול לשבועה!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' אבא: הוי\u0004 \u0005[הרי זה]\u0006 מקרה של \u0003מחויב שבועה שאינו יכול לישבע,\u0004 \u0003ו\u0004כלל הוא: \u0003כל המחויב שבועה שאינו יכול לישבע\u0004 — \u0003משלם.\u0004 עד כאן המקרה ב\"נסכא דר' אבא\". וסבורים היו חכמים שישבו לפני אביי כי לכאורה גם המקרה שלנו, כשיש רק עד אחד שמעיד שהחזיק בקרקע, והוא אינו יכול להישבע נגדו, שהרי גם הוא עצמו טוען שאכל מן הקרקע שלוש שנים — הרי זה מחויב שבועה שאינו יכול להישבע, וישלם על מה שאכל במשך אותו זמן כעדות אותו עד.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003התם סהדא לאורועי קאתי\u0004 \u0005[שם\u0006 ב\"נסכא דר' אבא\" \u0005העד להרע\u0006 את כוחו של החוטף \u0005הוא בא],\u0006 שהרי \u0003כי אתי אחרינא בהדיה מפקינן לה מיניה\u0004 \u0005[אם בא\u0006 עד \u0005אחר איתו מוציאים אנו אותה,\u0006 את חתיכת הכסף, \u0005ממנו],\u0006 \u0003הכא לסיועי קא אתי\u0004 \u0005[כאן לסייע\u0006 לטענת הקונה \u0005בא\u0006 העד\u0005],\u0006 שהרי \u0003כי אתא אחרינא מוקמינן לה בידיה\u0004 \u0005[כאשר יבוא\u0006 עד \u0005אחר נעמיד אותה,\u0006 את הקרקע, \u0005בידו],\u0006 ובמקרה כזה בודאי לא חייבה התורה שבועה!","\u0003אלא אי דמיא הא\u0004 \u0005[אם דומה\u0006 מקרה \u0005זה]\u0006 של \u0003ר' אבא\u0004 לטענות בדיני חזקות, הרי הוא דומה \u0003ל\u0004מקרה שהמחזיק טוען שקנה את הקרקע, ויש \u0003חד סהדא\u0004 \u0005[עד אחד]\u0006 המעיד שאכל את הפירות \u0003ולתרתי שני\u0004 \u0005[ו\u0006אולם \u0005לשתי שנים]\u0006 בלבד, \u0003ו\u0004השאלה נוגעת \u0003לפירי\u0004 \u0005[ל\u0006ענין \u0005פירות],\u0006 שבמקרה זה שני עדים היו מחייבים אותו לשלם, ונמצא העד האחד מחייבו שבועה, והוא אינו יכול להישבע שלא אכל, שהרי הוא עצמו טוען שאכל מן השדה, ומתוך שאינו יכול להישבע — הריהו משלם."],["מסופר: \u0003ההוא ארבא דהוו מינצו עלה בי תרי\u0004 \u0005[אוניה אחת שהיו רבים עליה שניים],\u0006 \u0003האי\u0004 \u0005[זה]\u0006 \u0003אמר \"דידי\u0004 \u0005[שלי]\u0006 \u0003היא\" והאי\u0004 \u0005[וזה]\u0006 \u0003אמר \"דידי\u0004 \u0005[שלי]\u0006 \u0003היא\",\u0004 \u0003אתא חד מינייהו לבי דינא\u0004 \u0005[בא אחד מהם לבית הדין]\u0006 \u0003ואמר: תיפסוה אדמייתינא סהדי דדידי\u0004 \u0005[עד שאביא עדים ששלי]\u0006 \u0003היא,\u0004 ונשאלה השאלה: האם \u0003תפסינן\u0004 \u0005[תופסים אנו]\u0006 בשבילו, \u0003או לא תפסינן\u0004 \u0005[אין אנו תופסים]?\u0006 \u0003רב הונא אמר: תפסינן\u0004 \u0005[תופסים אנו].\u0006 \u0003רב יהודה אמר: לא תפסינן\u0004 \u0005[אין אנו תופסים],\u0006 שאין מקום כאן לבית הדין להתערב.","ושואלים: אם תפסו בית דין את האניה, ואחר כך \u0003אזל\u0004 \u0005[הלך]\u0006 אותו אדם \u0003ולא אשכח סהדי\u0004 \u0005[מצא עדים],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 לדיינים: \u0003אפקוה\u0004 \u0005[הוציאו אותה]\u0006 מרשותכם, \u0003וכל דאלים גבר\u0004 \u0005[החזק יגבר],\u0006 כלומר, נעמיד את הדבר הזה כדין כל ספק שאין לו הכרעה מכח חזקה או עדות, האם \u0003מפקינן\u0004 \u0005[מוציאים אנו]\u0006 \u0003או לא מפקינן\u0004 \u0005[אין אנו מוציאים]?\u0006 \u0003רב יהודה אמר: לא מפקינן\u0004 \u0005[אין אנו מוציאים],\u0006 \u0003רב פפא אמר: מפקינן\u0004 \u0005[מוציאים אנו].\u0006 \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003לא תפסינן\u0004 \u0005[אין אנו תופסים]\u0006 מלכתחילה במקרה של ספק בעלות, \u0003והיכא\u0004 \u0005[ובמקום]\u0006 ש\u0003תפס\u0004 — \u0003לא מפקינן\u0004 \u0005[אין אנו מוציאים].\u0006","ועוד דין בענין זה: שנים שנתווכחו ביניהם על דבר, \u0003זה אומר \"\u0004הדבר \u0003של אבותי\" וזה אומר \"של אבותי\",\u0004 ואין בידם חזקה או ראיות, \u0003אמר רב נחמן: כל דאלים גבר\u0004 \u0005[החזק יגבר]\u0006 ויקח, שאין בית הדין מתערב בענין זה. ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה\u0006 הדבר\u0005]\u0006 \u0003משני שטרות היוצאין ביום אחד,\u0004 שיש לשני אנשים שונים שני שטרות קנין על שדה אחד, והם כתובים באותו תאריך,"],["\u0003רב אמר:\u0004 במקרה כזה \u0003יחלוקו\u0004 שני הטוענים, \u0003ושמואל אמר: שודא דדייני\u0004 \u0005[הכרעת הדיינים]\u0006 שעושים כפי שנראה להם. ומדוע כאן פסק רב נחמן \"כל דאלים גבר\"? ומשיבים: \u0003התם ליכא למיקם עלה דמילתא\u0004 \u0005[שם\u0006 בענין השטר \u0005אי אפשר לעמוד על הדבר],\u0006 כי אין כל דרך להוכיח מי קדם, והספק יישאר תמיד, ויש צורך להכריע בדבר. \u0003הכא איכא\u0004 \u0003למיקם עלה דמילתא\u0004 \u0005[כאן אפשר לעמוד על הדבר]\u0006 שהרי ייתכן שצד אחד ימצא עדים ויתברר הענין.","ושואלים: \u0003ומאי שנא מהא דתנן\u0004 \u0005[ומה שונה\u0006 דבר זה \u0005מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המחליף פרה בחמור וילדה\u0004 בינתיים הפרה, \u0003וכן המוכר שפחתו וילדה, זה\u0004 המוכר \u0003אומר: עד שלא מכרתי ילדה\u0004 והוולד הוא איפוא שלי, \u0003וזה אומר משלקחתי\u0004 (לאחר שלקחתי, קניתי) \u0003ילדה\u0004 ולכן הוולד הוא שלי — במקרה כזה \u0003יחלוקו?\u0004 ומדוע לא נכריע בדרך של \"כל דאלים גבר\" או \"שודא דדייני\"?","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003להאי\u0004 \u0005[ל\u0006טוען \u0005זה]\u0006"],["\u0003אית ליה דררא דממונא, ולההוא אית ליה דררא דממונא\u0004 \u0005[יש לו גרר,\u0006 זיקה, ממשות, \u0005של ממון, ולאחר יש לו\u0006 גם כן \u0005גרר של ממון],\u0006 כלומר, יש צד בעלות לכל אחד מהם, ולכך יתנו בית הדין מחצית לכל אחד. \u0003הכא\u0004 \u0005[כאן],\u0006 במקרים האחרים — \u0003אי דמר לא דמר, ואי דמר לא דמר\u0004 \u0005[אם של זה\u0006 היא \u0005אינה של זה, ואם של זה לא של זה]\u0006 ואם נחלק — נמצא בוודאות כי אחד מהם מקבל דבר שאינו שלו מיד בית הדין.","ובענין זה של דבר ששניים רבים עליו, ואין חזקה ולא ראיה לאחד מהם, \u0003אמרי נהרדעי\u0004 \u0005[אמרו חכמי\u0006 העיר \u0005נהרדעא]:\u0006 \u0003אם בא אחד מן השוק\u0004 שאין לו תביעה כלל \u0003והחזיק בה\u0004 — \u0003אין מוציאין אותה מידו. דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: גזלן של רבים\u0004 שאין ידוע ממי גזל \u0003לאו שמיה\u0004 \u0005[אין שמו\u0006 אינו נחשב\u0005]\u0006 \u0003גזלן,\u0004 שאינו חייב בהשבה לאדם מסויים, ואי אפשר להוציא ממנו. ולכן אף במקרה זה, כיון שאין לאחד מהם ראיה שהקרקע שלו — אי אפשר להוציא מן הזר שלקח.","\u0003רב אשי אמר: לעולם\u0004 אף גזלן של רבים \u0003שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003גזלן\u0004 ומוציאים מידו, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003גזלן\"?\u0004 לא לענין שאי אפשר להוציא מידו, אלא \u0003שלא ניתן להשבון\u0004 לרבים שגזל מהם, שאינו יכול לעשות תשובה שלימה.","מכאן חוזרים שוב לפירוש המשנה, שנינו בה רשימת נכסים, ובתוכם שדות, ש\u0003חזקתן שלש שנים מיום ליום וכו'. אמר ר' אבא:\u0004 יש מקרים שהחזקה נוצרת מיד, כגון \u0003אי דלי ליה איהו גופיה צנא דפירי\u0004 \u0005[אם הביא לו\u0006 למחזיק בשדה \u0005הוא עצמו,\u0006 המערער, \u0005סל של פירות]\u0006 מאותו שדה, \u0003לאלתר הוי\u0004 \u0005[מיד הרי זו]\u0006 \u0003חזקה\u0004 ואין מקבלים את טענתו, שהרי הוא עצמו מסר לו. \u0003אמר רב זביד: ואם טען\u0004 בעל השדה הראשון \u0003ואמר:\u0004 \u0003לפירות\u0004 בלבד \u0003הורדתיו\u0004 לשדי (כגון שהוא אריס בשדה) — הרי זה \u0003נאמן. והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 שיכול לטעון טענה זו, דווקא \u0003בתוך שלש\u0004 שנים, \u0003אבל לאחר שלש\u0004 שנים שהחזיק בה שנות חזקה — \u0003לא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: אי לפירא אחתיה, מאי הוה ליה למעבד\u0004 \u0005[אם לפירות הורידו, מה היה לו\u0006 לבעל השדה \u0005לעשות]\u0006 שלא תיחשב זאת לחזקה לאחר שלוש שנים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איבעי ליה למחויי\u0004 \u0005[היה לו למחות]\u0006 בתוך שלוש השנים הראשונות, ולהודיע שנתן לו רק זכות שימוש לפירות.","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שצריך למחות, \u0003הני\u0004 \u0005[אותם]\u0006 שטרות \u0003של\u0004 \u0003משכנתא\u0004 הנהוגה בעיר \u0003סורא\u0004 שהמלווה מקבל קרקע של הלווה ומשתמש בה, ועל ידי כך גובה את חובו, \u0003דכתב בהו\u0004 \u0005[שכותבים בהן\u0006 כך\u0005]:\u0006 \u0003\"במשלם שניא אלין תיפוק ארעא דא\u0004 \u0005[בסוף שנים אלה תצא קרקע זו]\u0006 \u0003בלא כסף\u0004 ותחזור לבעליה \u0003\",\u0004 \u0003אי כביש ליה\u0004 \u0005[אם יחביא\u0006 המלוה \u0005אותו]\u0006 את \u0003שטר\u0004 ה\u0003משכנתא גביה\u0004 \u0003ואמר\u0004 \u0005[אצלו ויאמר]:\u0006 \u0003לקוחה היא בידי,\u0004 ויש לו עדים שאכל שנות חזקה, \u0003הכי נמי דמהימן\u0004 \u0005[כך גם כן\u0006 נאמר \u0005שנאמן]?\u0006 וכי \u0003מתקני רבנן מידי דאתי ביה לידי פסידא\u0004 \u0005[מתקנים חכמים דבר שיבואו בו\u0006 אנשים \u0005לידי הפסד]?\u0006 \u0003אלא\u0004 ודאי \u0003איבעי ליה למחויי\u0004 \u0005[היה לו למחות]\u0006 במשך השנים ולהודיע שהשדה שלו, \u0003הכא נמי איבעי ליה למחויי\u0004 \u0005[כאן גם כן היה לו למחות].\u0006","\u0003אמר רב יהודה אמר רב: ישראל הבא מחמת גוי\u0004 שתביעתו לקרקע היא מחמת גוי שמכרה או נתנה לו — \u0003הרי הוא כגוי, מה גוי\u0004 — \u0003אין לו חזקה אלא בשטר, אף ישראל הבא מחמת גוי\u0004 — \u0003אין לו חזקה אלא בשטר. אמר רבא, ואי\u0004 \u0005[ואם]\u0006 \u0003אמר ישראל\u0004 לקונה:"],["\u0003לדידי\u0004 \u0005[לי\u0006 עצמי\u0005]\u0006 \u0003אמר לי\u0004 ה\u0003גוי דמינך זבנה\u0004 \u0005[שממך קנה אותה]\u0006 — \u0003מהימן\u0004 \u0005[נאמן].\u0006 ותוהים: \u0003מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003אילו\u0004 ה\u0003גוי\u0004 עצמו \u0003אמר לא מהימן\u0004 \u0005[היה אומר אינו נאמן],\u0006 \u0003ואילו אמר ישראל משמיה\u0004 \u0005[משמו]\u0006 של \u0003גוי\u0004 הריהו \u0003מהימן\u0004 \u0005[נאמן]?\u0006","\u0003אלא אמר רבא, אי\u0004 \u0005[אם]\u0006 \u0003אמר ישראל: קמי דידי זבנה\u0004 \u0005[לפני קנה אותה]\u0006 ה\u0003גוי מינך\u0004 \u0005[ממך]\u0006 \u0003וזבנה ניהלי\u0004 \u0005[ומכר אותה לי]\u0006 — \u0003מהימן\u0004 \u0005[נאמן],\u0006 \u0003מיגו דאי בעי אמר ליה\u0004 \u0005[מתוך שאם היה רוצה\u0006 לשקר \u0005היה אומר לו]:\u0006 \u0003אנא זבינתה מינך\u0004 \u0005[אני קניתי אותה ממך].\u0006","\u0003ו\u0004עוד בענייני נאמנות \u0003אמר רב יהודה: האי מאן דנקיט מגלא ותובליא, ואמר\u0004 \u0005[מי שמחזיק מגל וחבל, ואומר]:\u0006 \u0003איזיל איגזרה לדקלא דפלניא דזבנתיה מיניה\u0004 \u0005[אלך\u0006 ו\u0005אגזור את\u0006 פירות \u0005דקל של פלוני שקניתי אותו ממנו]\u0006 — \u0003מהימן\u0004 \u0005[נאמן],\u0006 וטעמו של דבר: \u0003לא חציף איניש למיגזר דקלא דלאו דיליה\u0004 \u0005[אין אדם מתחצף לגזור דקל שאינו שלו].\u0006","\u0003ו\u0004עוד \u0003אמר רב יהודה: האי מאן דאחזיק מגודא דערודי ולבר\u0004 \u0005[מי שמחזיק\u0006 בשדה \u0005מקיר הערודים והחוצה]\u0006 שהיו עושים גדרות סמוך לגבול השדה, כדי שלא יכנסו שם חמורי הבר וישחיתו, והחזיק אותו אדם בחלקה שמחוץ לגדר — \u0003לא הוי\u0004 \u0005[אין זו]\u0006 \u0003חזקה\u0004 אף שלא מחו הבעלים בתוך שלוש שנים; \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מימר אמר\u0004 \u0005[אומר]\u0006 בעל השדה בליבו: \u0003כל דזרע\u0004 \u0005[ש\u0006הוא \u0005זורע]\u0006 \u0003נמי ערודי אכלי ליה\u0004 \u0005[גם כן הערודים אוכלים אותו]\u0006 ולכן אינו מעכב בידי מי שמשתמש בחלקה זו, ואינו מוחה בידו.","\u0003ו\u0004עוד \u0003אמר רב יהודה:\u0004 אם \u0003אכלה\u0004 כשהיא \u0003ערלה\u0004 (בשלוש השנים הראשונות של העצים) — \u0003אינה חזקה.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אכלה ערלה,\u0004 או שאחת מן השנים בהן אכל את השדה היתה \u0003שביעית\u0004 ועשה בה מלאכה האסורה בשביעית וכתוצאה ממנה גדלו פירות אותם הוא אכל, \u0003ו\u0004כן אם אכל מפירות \u0003כלאים\u0004 שגדלו בה, שאסור לאכול את פירותיהם — \u0003אינה חזקה,\u0004 שאין בעל השדה מקפיד על אדם הנהנה משדהו בדבר שאסור ליהנות ממנו.","\u0003אמר רב יוסף:\u0004 אם \u0003אכלה\u0004 את השדה בעודה \u0003שחת\u0004 ולא המתין עד שתתבשל התבואה — \u0003לא הוי\u0004 \u0005[אין זו]\u0006 \u0003חזקה. אמר רבא: ואי\u0004 \u0005[ואם]\u0006 \u0003בצואר\u0004 (במיצר) \u0003מחוזא קיימא\u0004 \u0005[עומדת\u0006 השדה\u0005]\u0006 — \u0003הוי\u0004 \u0005[הרי זו]\u0006 \u0003חזקה,\u0004 אם לא מחה הבעלים, מפני שהיו רגילים לקצור שם תבואה למאכל בהמות.","\u0003אמר רב נחמן: תפתיחא\u0004 \u0005[קרקע פתוחה,\u0006 מבוקעת\u0005]\u0006 אם השתמש — \u0003לא הוי\u0004 \u0005[אין היא]\u0006 \u0003חזקה,\u0004 שאין תבואה גדלה היטב שם, ואין הבעלים מקפידים אם משתמש בה אחר. וכן אם קרקע שבה \u0003אפיק כורא ועייל כורא\u0004 \u0005[מוציא,\u0006 זורע בה \u0005כור, ומכניס\u0006 ממנה \u0005כור]\u0006 — \u0003לא הוי\u0004 \u0005[אין זו]\u0006 \u0003חזקה,\u0004 שמפני גריעות הקרקע, שאין בה רווח, לא דאגו הבעלים למחות.","\u0003ו\u0004עוד אמר: \u0003הני דבי ריש גלותא\u0004 \u0005[ואותם\u0006 אנשים \u0005מבית ראש הגולה]\u0006 — \u0003לא מחזקי בן ולא מחזקינן בהו\u0004 \u0005[אין\u0006 הם \u0005עושים חזקה בנו,\u0006 בשדותינו, \u0005ואין אנו עושים חזקה בהם],\u0006 שמפני שהיו תקיפים ואלימים, פעמים שלוקחים שדה שלא כדין ויראים הבעלים למחות בהם. ומצד שני מחמת עושרם פעמים לא היו מקפידים אם אחר משתמש בשדותיהם.","שנינו במשנה ש\u0003העבדים\u0004 הם כקרקע לענין חזקה. ושואלים: האם \u0003עבדים יש להם חזקה\u0004 כלל\u0003? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש: הגודרות\u0004 (בעלי חיים ההולכים מעצמם ממקום למקום), \u0003אין להן חזקה,\u0004 שכיון שהן יוצאות ונודדות מעצמן, שמא תפס אותן המחזיק בהן שלא כדין! \u0003אמר רבא:\u0004 הכוונה היא ש\u0003אין להן\u0004 לגודרות \u0003חזקה לאלתר\u0004 \u0005[מיד],\u0006 שההחזקה בהן כשלעצמה אינה הוכחה לבעלות עליהן, \u0003אבל יש להן חזקה לאחר שלש שנים\u0004 שהחזיק בהן, שבפרק זמן כזה צריכים היו הבעלים למחות בהם.","\u0003אמר רבא: אם היה\u0004 עבד \u0003קטן מוטל בעריסה\u0004 — \u0003יש לו\u0004 למחזיק בו \u0003חזקה לאלתר\u0004 \u0005[מיד].\u0006 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005]\u0006 הרי הוא אינו הולך ממקום למקום! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרך]\u0006 הדבר להיאמר אלא למקרה \u0003דאית ליה אימא\u0004 \u0005[שיש לו אם],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניחוש דלמא אימיה עיילתיה להתם\u0004 \u0005[נחשוש שמא אימו הכניסה אותו לשם]\u0006 ושכחה אותו במקום, על כן \u0003קא משמע לן אימא לא מנשיא ברא\u0004 \u0005[השמיע לנו\u0006 רבא ש\u0005אם אינה שוכחת\u0006 את \u0005בנה],\u0006 ואם הוא נמצא שם, ולא מחה הבעלים מיד — מן הסתם כדין הוא נמצא.","מסופר: \u0003הנהו עיזי\u0004 \u0005[עיזים]\u0006 ש\u0003אכלו חושלא\u0004 \u0005[תבואה קלופה]\u0006 שהיתה שטוחה בשדה \u0003ב\u0004עיר \u0003נהרדעא. אתא מרי חושלא תפסינהו\u0004 \u0005[בא בעל התבואה תפסן,\u0006 את העיזים\u0005]\u0006 \u0003והוה קא טעין טובא\u0004 \u0005[והיה טוען הרבה],\u0006 תובע סכומים גדולים שטען שהזיקו לו העיזים. \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל: יכול לטעון עד כדי דמיהן\u0004 של העזים שתפס, \u0003דאי בעי אמר\u0004 \u0005[שאם היה רוצה\u0006 לשקר \u0005היה יכול לומר]:\u0006 \u0003לקוחות\u0004 \u0003הן בידי,\u0004 ובכח טענה זאת — נאמן, אבל לא יותר מכן. ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש: הגודרות אין להן חזקה\u0004 ואם כן לא יכול היה לטעון כך! ומשיבים: \u0003שאני עיזי דמסירה\u0004 \u0005[שונות\u0006 הן \u0005עיזים ש\u0006הן \u0005מסורות]\u0006 \u0003לרועה,\u0004 ולכן אינן נודדות בעצמן, ואינן בכלל גודרות, ויש להן חזקה.","ומקשים: \u0003והא איכא צפרא ופניא\u0004 \u0005[והרי יש בוקר וערב]\u0006 שאף שהרועה מוציא אותן מחוץ לעיר, מכל מקום בבוקר ובערב הן הולכות לבדן בעיר כל אחת למקומה, ושמא תפסן משם! ומשיבים: הרי מעשה זה היה \u0003בנהרדעא\u0004 ושם \u0003טייעי שכיחי\u0004 \u0005[ערבים נוודים מצויים]\u0006 והם היו חשודים לגנוב את העיזים, \u0003ו\u0004לכן \u0003מידא לידא משלמי\u0004 \u0005[מיד ליד נותנים,\u0006 מעבירים אותן\u0005]\u0006 ואין מניחים להן ללכת לבד.","שנינו במשנה ש\u0003ר' ישמעאל אומר: שלשה חדשים\u0004 בשנה ראשונה, שנים עשר בשניה ושלושה בשלישית — דיים לחזקת שלוש שנים בשדה בעל. ור' עקיבא אומר: חודש בשנה הראשונה והשלישית ושנים עשר בשניה. ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי בענין \u0003ניר,\u0004 חרישה, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 מחלוקת\u0005],\u0006 ש\u0003ר' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \u0003ניר לא הוי\u0004 \u0005[איננו]\u0006 \u0003חזקה,\u0004 ולכן צריך לשהות שלושה חדשים עד שתצמח תבואה, \u0003ו\u0004אילו \u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 שאפילו \u0003ניר הוי\u0004 \u0005[הריהו]\u0006 \u0003חזקה\u0004 ודי לו בחודש?","ותוהים: \u0003ותסברא\u0004 \u0005[ו\u0006כי \u0005יכול אתה לסבור כן]?\u0006 אם כן, \u0003לר' עקיבא\u0004 שסבור לדרך זו שהחרישה היא עצמה חזקה, \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 אמר \u0003חודש?\u0004"],["\u0003אפילו יום אחד נמי\u0004 \u0005[גם כן]\u0006 יהא חזקה אם עשה בו את הניר! \u0003אלא דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003ניר\u0004 בלבד \u0003לא הוי\u0004 \u0005[אין הוא]\u0006 \u0003חזקה, והכא פירא רבא ופירא זוטא איכא בינייהו\u0004 \u0005[וכאן\u0006 בענין \u0005פרי גדול ופרי קטן יש ביניהם\u0006 מחלוקת\u0005].\u0006 שלדעת ר' ישמעאל צריך שתהא החזקה משך זמן גידול של פרי גדול, שגדל בשלושה חדשים, כגון של תבואה וקטניות. ולר' עקיבא אף בזמן גידול של פרי קטן, שגדל במשך חודש, כגון ירק, יש חזקה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ניר,\u0004 חרישה, \u0003אינו חזקה, ויש אומרים: הרי זה חזקה.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003\"יש אומרים\"\u0004 אלה? \u0003אמר רב חסדא:\u0004 שיטת \u0003ר' אחא היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם \u0003נרה\u0004 (חרש) את השדה \u0003שנה\u0004 ולא זרע בה, אלא השאיר את האדמה שתנוח, \u0003וזרעה שתים\u0004 שתי שנים, או \u0003נרה שתים וזרעה שנה\u0004 — \u0003אינה חזקה; ר' אחא אומר: הרי זו חזקה.\u0004 משמע שהוא סבור שניר הוא חזקה.","\u0003אמר רב אשי, שאלית\u0004 \u0005[שאלתי]\u0006 את \u0003כל גדולי הדור\u0004 בהלכה זו, \u0003ואמרו לי: ניר הרי זה חזקה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ביבי לרב נחמן: מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]\u0006 ש\u0003ניר הוי\u0004 \u0005[הריהו]\u0006 \u0003חזקה?\u0004 — שכן \u0003לא עביד איניש דכריבו ליה לארעיה ושתיק\u0004 \u0005[אין אדם עשוי שיחרשו את אדמתו וישתוק].\u0006 \u0003ומאי טעמא דמאן דאמר\u0004 \u0005[ומה הטעם של מי שאומר]\u0006 \u0003ניר לא הוי\u0004 \u0005[איננו]\u0006 \u0003חזקה? מימר אמר\u0004 \u0005[אומר]\u0006 בעל השדה בליבו: \u0003כל שיבא ושיבא דכרבו, לעייל ביה\u0004 \u0005[פיסה ופיסה שיחרשו, שייכנס בו],\u0006 שיחרשו אחרים עבורי בשדה בחינם, ואחר כך אשתמש אני בכך.","מסופר, \u0003שלחו ליה\u0004 \u0005[ליה]\u0006 \u0003בני\u0004 העיר \u0003פום נהרא לרב נחמן בר רב חסדא\u0004 שאלה זו: \u0003ילמדנו רבינו,\u0004 האם \u0003נירא הוי\u0004 \u0005[ניר הריהו]\u0006 \u0003חזקה, או לא הוי\u0004 \u0005[איננו]\u0006 \u0003חזקה? אמר להו\u0004 \u0005[להם],\u0006 \u0003ר' אחא וכל גדולי הדור אמרי\u0004 \u0005[אומרים]:\u0006 \u0003ניר הרי זה חזקה.\u0004","\u0003אמר רב נחמן בר יצחק:\u0004 וכי \u0003רבותא למיחשב גברי\u0004 \u0005[גדולה\u0006 היא \u0005למנות אנשים]\u0006 חכמים, התומכים בדעה מסויימת, בלא להביא בחשבון את דעות החולקים? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רב ושמואל בבבל, ור' ישמעאל ור' עקיבא בארץ ישראל אמרי\u0004 \u0005[אומרים]:\u0006 \u0003ניר לא הוי\u0004 \u0005[איננו]\u0006 \u0003חזקה!\u0004","ומסבירים מנין שכן היא דעתם: \u0003ר' ישמעאל ור' עקיבא\u0004 — \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא\u0004 כפי שביארנו. אמרתו של \u0003רב\u0004 — \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 ש\u0003אמר רב יהודה אמר רב:\u0004 הלכה \u0003זו\u0004 האמורה במשנה, שדי בחודש או בשלושה בשנה הראשונה והשלישית — \u0003דברי ר' ישמעאל ור' עקיבא\u0004 בלבד היא, \u0003אבל חכמים אומרים: חזקתה שלש שנים מיום ליום,\u0004 והלכה כמותם, וכשאמר \u0003\"מיום ליום\" למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 \u0003לאו למעוטי\u0004 \u0005[האם לא למעט]\u0006 \u0003ניר\u0004 ש\u0003לא\u0004 נחשב חזקה?","\u0003שמואל\u0004 — \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 ש\u0003אמר רב יהודה אמר שמואל: זו,\u0004 משנתנו, לפיה בשדה האילן, אם בשנה אחת עשה שלוש פעולות של איסוף — של תבואה, זיתים ותאנים — הרי זו חזקה, \u0003דברי ר' ישמעאל ור' עקיבא\u0004 היא, \u0003אבל חכמים אומרים:\u0004 אין זו חזקה \u0003עד שיגדור שלש גדירות\u0004 של תמרים, \u0003ו\u0004כן אם \u0003יבצור שלש בצירות\u0004 של ענבים \u0003וימסוק שלש מסיקות\u0004 של זיתים, והלכה כמותם. ואם כן אף לדעתו, ניר של שלוש שנים אינו עושה חזקה, אלא דווקא לקיטה של פירות. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין רב ושמואל? \u0003אמר אביי: דקל נערה\u0004 (צעיר) \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 \u0003שעושה שלש פעמים בשנה\u0004 ונחלקו האם שלוש גדירות נחשבות כחזקה גם אם היו בפחות משלוש שנים מלאות.","שנינו במשנתנו, \u0003אמר ר' ישמעאל: במה דברים אמורים\u0004 שצריך שלוש שנים לחזקה? — \u0003בשדה הלבן\u0004 (שדה תבואה), אבל לא בשדה האילן. שבשדה האילן אם קטף שלושה מיני פירות בזמנים שונים הרי זו חזקה. \u0003אמר אביי: מ\u0004דברי \u0003ר' ישמעאל נשמע\u0004 ונבין \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים עליו, ומצריכים שלוש שנות לקיטה של אותו סוג פרי, שאם \u0003היו לו שלשים אילנות\u0004 בני אותו סוג, שהיו נטועים כדרכם בצפיפות של \u0003מטע עשרה ל\u0004שטח של \u0003בית סאה,\u0004 אם \u0003אכל עשרה\u0004 מהם \u0003בשנה זו ועשרה בשנה זו ועשרה בשנה זו\u0004 — \u0003הרי זו חזקה.\u0004"],["\u0003לאו מי\u0004 \u0005[האם לא]\u0006 \u0003אמר ר' ישמעאל:\u0004 איסוף של \u0003חד פירא\u0004 \u0005[פרי אחד]\u0006 שמהווה רק חלק מן השדה \u0003הוי\u0004 \u0005[הריהו]\u0006 מעשה של \u0003חזקה לכולהו פירי\u0004 \u0005[לכל הפירות]?\u0006 \u0003הכא נמי, הני הוו\u0004 \u0005[כאן גם כן אלה נעשים]\u0006 \u0003חזקה להני\u0004 \u0005[לאלה],\u0006 \u0003והני הוו\u0004 \u0005[ואלה נעשים]\u0006 \u0003חזקה להני\u0004 \u0005[לאלה].\u0006","ומעירים: \u0003והני מילי היכא\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא \u0005במקום]\u0006 ש\u0003לא אפיקו\u0004 \u0005[הוציאו]\u0006 עשרים האילנות האחרים פירות, שאכל בכל שנה את כל הפירות שהוציא השדה באותה שנה. \u0003אבל\u0004 אם \u0003אפיקו\u0004 \u0005[הוציאו]\u0006 פרי \u0003ולא אכל\u0004 מהם — \u0003לא הויא\u0004 \u0005[אינה]\u0006 \u0003חזקה\u0004 על אילנות שלא אכל מהם. ומוסיפים: ומה שנאמר שלקיטה מאילנות שונים בכל שנה הריהי חזקה לכל השדה — \u0003והוא דבאזי באזוזי\u0004 \u0005[ש\u0006היו \u0005מפוזרים]\u0006 האילנות בכל השדה, ולכן אפשר לומר שחזקה לאחדים מהם היא חזקה לכולם. אבל אם היו האילנות שאכל מפירותיהם מרוכזים בפינה מסויימת — אינה חזקה אלא לאותה פינה.","ואגב ענין זה עלתה השאלה הבאה: שני אנשים שהחזיקו בשדה אילנות, \u0003זה,\u0004 אדם אחד, \u0003החזיק באילנות\u0004 שבשדה, \u0003וזה,\u0004 האחר, \u0003החזיק בקרקע,\u0004 מה משמעות הדבר לענין בעלות? \u0003אמר רב זביד: זה קנה אילנות וזה קנה קרקע. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: אם כן,\u0004 לדבריך, ש\u0003אין לו לבעל אילנות בקרקע כלום, לימא ליה\u0004 \u0005[שיאמר לו]\u0006 \u0003בעל קרקע לבעל אילנות: עקור\u0004 מהקרקע שלי את \u0003אילנך\u0004 \u0005[אילנותיך],\u0006 \u0003שקול וזיל\u0004 \u0005[קח ולך]!\u0006 \u0003אלא אמר רב פפא: זה קנה אילנות וחצי קרקע, וזה קנה חצי קרקע.\u0004 ומתוך כך דנים בבעיה אחרת הנוגעת למכירה של שדה אילן.","ותחילה מקדימים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 שאם אדם \u0003מכר קרקע ושייר\u0004 לו באותה קרקע \u0003אילנות לפניו\u0004 (לעצמו) — \u0003יש לו קרקע\u0004 הנחוצה לאילנות אלה. \u0003ואפילו ל\u0004דעת \u0003ר' עקיבא\u0004 ש\u0003אמר: מוכר בעין יפה מוכר,\u0004 שאם מכר בית ושייר לעצמו את הבור שבתוכו, שמכר לקונה הכל ולא שייר לעצמו אפילו את הדרך לבור, הרי \u0003הני מילי גבי\u0004 \u0005[דברים אלה\u0006 אמורים \u0005אצל]\u0006 \u0003בור ודות\u0004 (מבנה לאגירת מים),","ש\u0003לא מכחשו בארעא\u0004 \u0005[מזיקים לקרקע]\u0006 שמסביב להם, ולא יבוא הקונה לטעון שהבור מזיקו ולכך שיסתום המוכר את בורו, ואשר על כן יצטרך המוכר מלכתחילה להשאיר לעצמו קרקע, ולכן, לפי הכלל שמוכר בעין יפה מוכר — אינו משייר לעצמו. \u0003אבל אילנות\u0004"],["\u0003דקמכחשי בארעא\u0004 \u0005[שהם מכחישים\u0006 ומקלקלים \u0005את הקרקע]\u0006 — ודאי \u0003שיורי\u0004 \u0005[לשייר]\u0006 \u0003שייר\u0004 לעצמו את הקרקע סביבות האילנות, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא שייר, לימא ליה\u0004 \u0005[יאמר לו]\u0006 הקונה: \u0003עקור אילנא וזיל\u0004 \u0005[\u0006את \u0005האילן ולך].\u0006","אבל במקרה ש\u0003מכר\u0004 לחבירו \u0003אילנות ו\u0004במפורש \u0003שייר קרקע לפניו\u0004 (לעצמו) — הרי בענין זה תהיה \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 \u0003ר' עקיבא ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003ל\u0004שיטת \u0003ר' עקיבא דאמר\u0004 \u0005[שאומר]:\u0006 \u0003מוכר בעין יפה מוכר\u0004 — \u0003אית ליה\u0004 \u0005[יש לו]\u0006 לקונה קרקע לצורך האילנות, \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 הסבורים שהמוכר בעין רעה מוכר — \u0003לית ליה\u0004 \u0005[אין לו]\u0006 קרקע כלל.","ומבארים: \u0003ל\u0004שיטת \u0003ר' עקיבא אית ליה\u0004 \u0005[יש לו]\u0006 קרקע, \u0003ואפילו ל\u0004דברי \u0003רב זביד\u0004 הסבור בענין שנים שהחזיקו בשדה וקנו אותה, האחד בקרקע והשני באילנות, ש\u0003אמר אין לו\u0004 לבעל האילנות קרקע, \u0003הני מילי גבי\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005אצל]\u0006 \u0003שני לקוחות, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 קונה הקרקע לקונה האילנות: \u0003כי היכי דלדידי לית\u0004 \u0005[כמו שלי אין]\u0006 \u0003לי\u0004 זכות \u0003באילנות, לדידך נמי לית\u0004 \u0005[לך גם כן אין]\u0006 \u0003לך\u0004 כל זכות \u0003בקרקע, אבל הכא\u0004 \u0005[כאן]\u0006 — \u0003מוכר בעין יפה מוכר,\u0004 ומן הסתם נתן לקונה קרקע כפי הנחוץ לאילנות.","ומן הצד השני \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 האומרים שבעין רעה מוכר \u0003לית ליה\u0004 \u0005[אין לו]\u0006 בקרקע כלום, \u0003ואפילו לרב פפא\u0004 ש\u0003אמר\u0004 בשני לקוחות ש\u0003יש לו\u0004 מחצית, \u0003הני מילי גבי\u0004 \u0005[דברים אלה\u0006 אמורים \u0005אצל]\u0006 \u0003שני לקוחות, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל האילנות לבעל הקרקע: \u0003כי היכי דלדידך זבין\u0004 \u0005[כמו שלך מכר]\u0006 \u0003בעין יפה, לדידי נמי זבין\u0004 \u0005[לי גם כן מכר]\u0006 \u0003בעין יפה,\u0004 ושייר לי זכות הנאה מן הקרקע שבה מצויים האילנות. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 הולכים הם לשיטתם ש\u0003מוכר בעין רעה מוכר\u0004 ושייר לעצמו מה שלא מכר בפירוש.","\u0003אמרי נהרדעי\u0004 \u0005[אמרו חכמי נהרדעא]:\u0006 האוכל מפירות שדה אילן במשך שלוש שנים, אם \u0003אכלן רצופין\u0004 (צפופים) שלא היו האילנות שאכל מהם נטועים כראוי, ברווח מתאים ביניהם, אלא היו צפופים בשדה — \u0003אין לו חזקה\u0004 בקרקע זו, שאין אילנות אלה עשויים להתקיים. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: אלא מעתה, האי מישרא דאספסתא במאי קני לה\u0004 \u0005[שדה זה של אספסת במה קונה אותו]\u0006 שבוודאי הוא נטוע בצפיפות רבה! \u0003אלא אמר רבא,\u0004 כך אמרו חכמי נהרדעא: אם \u0003מכרן רצופין\u0004 — \u0003אין לו קרקע\u0004 שבכלל הקונה שלושה אילנות או יותר, קונה איתם את הקרקע שסביבם, בתור שדה אילן. ואולם אילנות הגדלים בצפיפות כזו אין רגילים להשאיר אותם אלא הם עשויים להיעקר.","\u0003אמר ר' זירא,\u0004 דבר זה תלוי במחלוקת \u0003תנאי\u0004 \u0005[תנאים],\u0006 ששנינו: \u0003כרם שהוא נטוע על פחות מארבע אמות\u0004 בין גפן לגפן — \u0003ר' שמעון אומר: אינו\u0004 נחשב \u0003כרם,\u0004 לא לענין כלאיים ולא לענין אחר. \u0003וחכמים אומרים: הרי זו כרם,\u0004 למרות שאינו נטוע ככרם, \u0003ו\u0004טעם הדבר — כי \u0003רואין את האמצעיים,\u0004 את הגפנים היתירות שיש באמצע \u0003כאילו אינן,\u0004 ונמצא שיש שם כרם, אף שבינתיים אינו נטוע כראוי. ולפי דעת חכמים יש לפרש שאם מכרם — מכר עימם את הקרקע.","ועוד \u0003אמרי נהרדעי\u0004 \u0005[אמרו חכמי נהרדעא]:\u0006 \u0003האי מאן דזבין דקלא לחבריה\u0004 \u0005[מי שמוכר דקל לחבירו]\u0006 — \u0003קני ליה משפוליה\u0004 \u0005[קונה אותו\u0006 ואת הקרקע \u0005מתחתיתו]\u0006 \u0003עד תהומא\u0004 \u0005[התהום].\u0006"]]};
